css:
/* The whole helix is driven by one registered number. Every card and every
   thread bead derives its own angle, height, fade and shading from
   (--i − --fxd-helix-pos) with calc() and cos(), so a single transition on
   the root screws the spiral; JS only ever writes that one value. */
@property --fxd-helix-pos { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --fxd-helix-year { syntax: "<integer>"; inherits: true; initial-value: 1898; }
@property --fxd-helix-sway { syntax: "<angle>"; inherits: true; initial-value: 0deg; }

.fxd-helix {
  /* Re-theme with these four. */
  --fxd-helix-bg: oklch(0.27 0.045 168);
  --fxd-helix-card: oklch(0.965 0.018 92);
  --fxd-helix-ink: oklch(0.25 0.03 168);
  --fxd-helix-accent: oklch(0.67 0.18 36);

  --fxd-helix-fg: color-mix(in oklch, var(--fxd-helix-card) 94%, var(--fxd-helix-bg));
  --fxd-helix-muted: color-mix(in oklch, var(--fxd-helix-card) 56%, var(--fxd-helix-bg));
  --fxd-helix-line: color-mix(in oklch, var(--fxd-helix-card) 15%, transparent);
  --fxd-helix-deep: color-mix(in oklch, var(--fxd-helix-bg) 70%, black);
  --fxd-helix-step: 30deg;
  --fxd-helix-spring: linear(0, 0.009, 0.035 2.1%, 0.141, 0.281 6.7%, 0.723 12.9%, 0.938 16.7%, 1.017, 1.077, 1.121, 1.149 24.3%, 1.159, 1.163, 1.161, 1.154 29.9%, 1.129 32.8%, 1.051 39.6%, 1.017 43.1%, 0.991, 0.977 51%, 0.974 53.8%, 0.975 57.1%, 0.997 69.8%, 1.003 76.9%, 1);
  --fxd-helix-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative;
  isolation: isolate;
  display: grid;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 4 / 5;
  min-block-size: 320px;
  max-block-size: 380px;
  padding: 14px 16px 16px;
  border-radius: 18px;
  overflow: hidden;
  background:
    radial-gradient(120% 70% at 50% 42%, color-mix(in oklch, var(--fxd-helix-bg) 82%, var(--fxd-helix-card)) 0%, transparent 62%),
    linear-gradient(var(--fxd-helix-bg), var(--fxd-helix-deep));
  color: var(--fxd-helix-fg);
  font-family: system-ui, sans-serif;
  transition: --fxd-helix-pos .95s var(--fxd-helix-spring), --fxd-helix-year .9s var(--fxd-helix-out);

  &[data-far] { transition: --fxd-helix-pos 1.25s cubic-bezier(.22, .9, .16, 1), --fxd-helix-year 1.15s var(--fxd-helix-out); }
  &[data-drag] { transition: --fxd-helix-year .5s var(--fxd-helix-out); }

  & .fxd-helix__body {
    display: grid;
    grid-template-areas: "head" "stage" "info";
    grid-template-rows: auto minmax(0, 1fr) auto;
    min-block-size: 0;
  }
  & .fxd-helix__head {
    grid-area: head;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 8px;
    position: relative;
    z-index: 2;
  }
  & .fxd-helix__mark {
    inline-size: 20px;
    block-size: 20px;
    fill: none;
    stroke: var(--fxd-helix-accent);
    stroke-width: 1.5;
    stroke-linecap: round;
  }
  & .fxd-helix__brand {
    margin: 0;
    font-size: 12px;
    font-weight: 650;
    letter-spacing: .08em;
    text-transform: uppercase;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  & .fxd-helix__span {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 0;
    font: 500 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxd-helix-muted);
  }
  & .fxd-helix__span i {
    inline-size: 18px;
    block-size: 1px;
    background: currentColor;
  }

  /* ── stage ── */
  & .fxd-helix__stage {
    grid-area: stage;
    container-type: inline-size;
    position: relative;
    min-block-size: 150px;
    perspective: 150cqi;
    perspective-origin: 50% 46%;
    outline: none;
    cursor: grab;
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
    margin-inline: -16px;
    mask-image: linear-gradient(transparent, #000 13%, #000 87%, transparent);
  }
  &[data-drag] .fxd-helix__stage { cursor: grabbing; }
  /* aria-activedescendant pattern: focus is drawn on the active option */
  & .fxd-helix__stage:focus-visible .fxd-helix__card[aria-selected="true"] {
    outline: 2px solid var(--fxd-helix-accent);
    outline-offset: 3px;
  }
  & .fxd-helix__spin {
    --r: 71cqi;
    --pitch: 6.5cqi;
    position: absolute;
    inset: 0;
    transform-style: preserve-3d;
    transform: translateY(-3cqi) translateZ(calc(var(--r) * -1)) rotateX(-12deg) rotateY(var(--fxd-helix-sway));
    animation: fxd-helix-sway 11s cubic-bezier(.45, 0, .55, 1) infinite alternate;
  }
  &[data-drag] .fxd-helix__spin,
  &[data-off] .fxd-helix__spin { animation-play-state: paused; }

  & .fxd-helix__axis {
    position: absolute;
    left: 50%;
    top: -10%;
    inline-size: 1px;
    block-size: 120%;
    background: linear-gradient(transparent, color-mix(in oklch, var(--fxd-helix-card) 9%, transparent) 25% 75%, transparent);
  }

  /* beads on the helix path, under the cards */
  & .fxd-helix__thread { position: absolute; inset: 0; transform-style: preserve-3d; }
  & .fxd-helix__thread i {
    --d: calc(var(--i) - var(--fxd-helix-pos));
    --n: max(calc(var(--i) - var(--fxd-helix-pos)), calc(var(--fxd-helix-pos) - var(--i)));
    position: absolute;
    left: 50%;
    top: 50%;
    inline-size: 1cqi;
    block-size: 1cqi;
    min-inline-size: 3px;
    min-block-size: 3px;
    margin: -1.5px;
    border-radius: 50%;
    background: var(--fxd-helix-accent);
    transform: translateY(calc(var(--d) * var(--pitch) * -1 + 15cqi)) rotateY(calc(var(--d) * var(--fxd-helix-step))) translateZ(var(--r));
    opacity: clamp(.1, calc((.45 + .45 * cos(var(--d) * var(--fxd-helix-step))) * (1.3 - var(--n) / 7)), 1);
  }

  /* ── cards ── */
  & .fxd-helix__card {
    --d: calc(var(--i) - var(--fxd-helix-pos));
    --n: max(calc(var(--i) - var(--fxd-helix-pos)), calc(var(--fxd-helix-pos) - var(--i)));
    --face: cos(var(--d) * var(--fxd-helix-step));
    position: absolute;
    left: 50%;
    top: 50%;
    box-sizing: border-box;
    inline-size: 38cqi;
    block-size: 24cqi;
    margin: -12cqi 0 0 -19cqi;
    display: grid;
    grid-template-areas: "year no" "title title";
    grid-template-columns: 1fr auto;
    grid-template-rows: auto 1fr;
    align-items: start;
    padding: 2.6cqi 3cqi 2.8cqi;
    border-radius: 2cqi;
    background:
      linear-gradient(var(--fxd-helix-accent), var(--fxd-helix-accent)) top / 100% 0 no-repeat,
      linear-gradient(170deg, var(--fxd-helix-card), color-mix(in oklch, var(--fxd-helix-card) 88%, var(--fxd-helix-ink)));
    color: var(--fxd-helix-ink);
    box-shadow:
      inset 0 0 0 1px color-mix(in oklch, var(--fxd-helix-ink) 10%, transparent),
      0 1.5cqi 4cqi -1cqi color-mix(in oklch, black 45%, transparent);
    transform: translateY(calc(var(--d) * var(--pitch) * -1)) rotateY(calc(var(--d) * var(--fxd-helix-step))) translateZ(var(--r));
    opacity: clamp(.14, calc(1.34 - var(--n) / 5), 1);
    filter: brightness(calc(.42 + .58 * max(var(--face), 0)));
    cursor: pointer;
    transition: background-size .45s var(--fxd-helix-out);
  }
  & .fxd-helix__card[aria-selected="true"] { background-size: 100% 1.2cqi, auto; }
  & .fxd-helix__card > * {
    opacity: clamp(0, calc(var(--face) * 3.2 - .9), 1);
  }
  & .fxd-helix__card b {
    grid-area: year;
    font-size: 8.6cqi;
    font-weight: 780;
    line-height: .9;
    letter-spacing: -.035em;
    font-variant-numeric: tabular-nums lining-nums;
  }
  & .fxd-helix__card i {
    grid-area: no;
    font: 500 2.6cqi/1 ui-monospace, Menlo, monospace;
    font-style: normal;
    letter-spacing: .04em;
    color: color-mix(in oklch, var(--fxd-helix-ink) 55%, var(--fxd-helix-card));
  }
  & .fxd-helix__card span {
    grid-area: title;
    align-self: end;
    font-size: 3.9cqi;
    font-weight: 620;
    line-height: 1.12;
    text-wrap: balance;
  }
  & .fxd-helix__card[aria-selected="true"] i { color: var(--fxd-helix-accent); }

  /* ── info ── */
  & .fxd-helix__info {
    grid-area: info;
    display: grid;
    grid-template-areas: "year nav" "copy copy";
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: end;
    column-gap: 10px;
    position: relative;
    z-index: 2;
    padding-block-start: 6px;
    border-block-start: 1px solid var(--fxd-helix-line);
  }
  & .fxd-helix__year {
    grid-area: year;
    margin: 0;
    font-size: clamp(30px, 12cqi, 46px);
    font-weight: 230;
    line-height: 1;
    letter-spacing: -.03em;
    font-variant-numeric: tabular-nums;
    counter-reset: fxd-helix-y var(--fxd-helix-year);
  }
  & .fxd-helix__year::before { content: counter(fxd-helix-y); }
  & .fxd-helix__copy { grid-area: copy; min-block-size: 3.6em; }
  & .fxd-helix__title {
    margin: 4px 0 2px;
    font-size: 14px;
    font-weight: 650;
    line-height: 1.2;
    text-wrap: balance;
  }
  & .fxd-helix__text {
    margin: 0;
    font-size: 12.5px;
    line-height: 1.4;
    color: var(--fxd-helix-muted);
    text-wrap: pretty;
  }
  & .fxd-helix__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  & .fxd-helix__nav {
    grid-area: nav;
    display: flex;
    align-items: center;
    gap: 6px;
    padding-block-end: 4px;
  }
  & .fxd-helix__count {
    min-inline-size: 5.2ch;
    text-align: center;
    font: 500 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxd-helix-muted);
  }
  & .fxd-helix__btn {
    display: grid;
    place-items: center;
    inline-size: 30px;
    block-size: 30px;
    padding: 0;
    border: 1px solid var(--fxd-helix-line);
    border-radius: 50%;
    background: color-mix(in oklch, var(--fxd-helix-card) 4%, transparent);
    color: var(--fxd-helix-fg);
    cursor: pointer;
    transition: background-color .2s, border-color .2s, scale .35s var(--fxd-helix-spring);
  }
  & .fxd-helix__btn svg {
    inline-size: 16px;
    block-size: 16px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.6;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxd-helix__btn:hover {
    background: color-mix(in oklch, var(--fxd-helix-accent) 22%, transparent);
    border-color: color-mix(in oklch, var(--fxd-helix-accent) 60%, transparent);
  }
  & .fxd-helix__btn:active { scale: .92; }
  & .fxd-helix__btn:disabled { opacity: .35; cursor: default; background: transparent; border-color: var(--fxd-helix-line); }
  & .fxd-helix__btn:focus-visible { outline: 2px solid var(--fxd-helix-accent); outline-offset: 2px; }

  @container (max-width: 300px) {
    & .fxd-helix__brand { font-size: 11px; letter-spacing: .05em; }
    & .fxd-helix__span i { inline-size: 10px; }
  }
  @container (min-width: 470px) {
    & .fxd-helix__body {
      grid-template-areas: "head head" "stage info";
      grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
      grid-template-rows: auto minmax(0, 1fr);
      column-gap: 18px;
    }

    & .fxd-helix__info {
      align-self: center;
      grid-template-areas: "year" "copy" "nav";
      grid-template-columns: minmax(0, 1fr);
      border-block-start: 0;
      padding-block-start: 0;
    }
    & .fxd-helix__copy { min-block-size: 6em; }
    & .fxd-helix__stage {
      margin-inline-end: 0;
      mask-image: linear-gradient(transparent, #000 13%, #000 87%, transparent), linear-gradient(90deg, #000 78%, transparent);
      mask-composite: intersect;
    }
    & .fxd-helix__nav { padding-block: 10px 0; }
  }
}

@keyframes fxd-helix-sway {
  from { --fxd-helix-sway: -7deg; }
  to { --fxd-helix-sway: 7deg; }
}

@media (prefers-reduced-motion: reduce) {
  .fxd-helix,
  .fxd-helix[data-far],
  .fxd-helix[data-drag] { transition: none; }
  .fxd-helix .fxd-helix__spin { animation: none; }
  .fxd-helix .fxd-helix__card,
  .fxd-helix .fxd-helix__btn { transition: none; }
}

js:
/* Helix timeline. The only value this script animates is --fxd-helix-pos on
   the root: CSS turns (--i − pos) into each card's height, angle, fade and
   shading, and a registered-property transition with a linear() spring does
   the screwing. Dragging writes pos directly (transition off), then releases
   onto the nearest card with the fling velocity carried into the target. */
const stage = root.querySelector('.fxd-helix__stage');
const cards = [...root.querySelectorAll('.fxd-helix__card')];
const thread = root.querySelector('.fxd-helix__thread');
const titleEl = root.querySelector('[data-k="title"]');
const textEl = root.querySelector('[data-k="text"]');
const srYear = root.querySelector('.fxd-helix__sr');
const copy = root.querySelector('.fxd-helix__copy');
const count = root.querySelector('.fxd-helix__count');
const [prevBtn, nextBtn] = root.querySelectorAll('.fxd-helix__btn');
const calm = matchMedia('(prefers-reduced-motion: reduce)');
const N = cards.length;
const uid = 'fxd-helix-' + Math.random().toString(36).slice(2, 8);

cards.forEach((c, i) => { c.id = uid + '-' + i; });

/* beads every sixth of a step along the same helix the cards ride */
let beads = '';
for (let t = -0.5; t <= N - 0.5 + 1e-6; t += 1 / 6) beads += '<i style="--i:' + t.toFixed(3) + '"></i>';
thread.innerHTML = beads;

let pos = parseFloat(getComputedStyle(root).getPropertyValue('--fxd-helix-pos')) || 0;
let active = Math.round(pos);
const pad = (n) => String(n).padStart(2, '0');

function writePos(p) {
  pos = p;
  root.style.setProperty('--fxd-helix-pos', p.toFixed(4));
}

function show(i, announce) {
  const c = cards[i];
  cards.forEach((k, j) => k.setAttribute('aria-selected', j === i ? 'true' : 'false'));
  stage.setAttribute('aria-activedescendant', c.id);
  root.style.setProperty('--fxd-helix-year', c.querySelector('b').textContent);
  count.textContent = pad(i + 1) + ' / ' + pad(N);
  prevBtn.disabled = i === 0;
  nextBtn.disabled = i === N - 1;
  if (!announce) return;
  srYear.textContent = c.querySelector('b').textContent + ': ';
  titleEl.textContent = c.querySelector('span').textContent;
  textEl.textContent = c.dataset.text;
  if (!calm.matches) {
    copy.getAnimations().forEach((a) => a.cancel());
    copy.animate(
      [{ opacity: 0, transform: 'translateY(6px)', filter: 'blur(3px)' }, { opacity: 1, transform: 'none', filter: 'none' }],
      { duration: 420, easing: 'cubic-bezier(.16,1,.3,1)' }
    );
  }
}

function go(i) {
  i = Math.max(0, Math.min(N - 1, i));
  root.toggleAttribute('data-far', Math.abs(i - pos) > 2.5);
  writePos(i);
  if (i !== active) { active = i; show(i, true); }
}

show(active, false);

/* ── buttons, keys, wheel ── */
root.querySelectorAll('.fxd-helix__btn').forEach((b) => {
  b.addEventListener('click', () => go(active + Number(b.dataset.step)));
});

stage.addEventListener('keydown', (e) => {
  const map = { ArrowUp: 1, ArrowRight: 1, ArrowDown: -1, ArrowLeft: -1, PageUp: 3, PageDown: -3 };
  if (e.key in map) go(active + map[e.key]);
  else if (e.key === 'Home') go(0);
  else if (e.key === 'End') go(N - 1);
  else return;
  e.preventDefault();
});

let wheelAcc = 0, wheelAt = 0;
stage.addEventListener('wheel', (e) => {
  const dir = Math.sign(e.deltaY || e.deltaX);
  /* let the page scroll on once the helix is at either end */
  if ((dir < 0 && active === N - 1) || (dir > 0 && active === 0)) return;
  e.preventDefault();
  const now = performance.now();
  if (now - wheelAt > 220) wheelAcc = 0;
  wheelAt = now;
  wheelAcc += e.deltaY || e.deltaX;
  if (Math.abs(wheelAcc) > 46) { go(active - Math.sign(wheelAcc)); wheelAcc = 0; }
}, { passive: false });

/* ── drag: horizontal spins, vertical climbs ── */
let drag = null;
stage.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const w = stage.clientWidth || 300;
  drag = { id: e.pointerId, x: e.clientX, y: e.clientY, p0: pos, w, moved: false, hist: [[performance.now(), pos]] };
});
stage.addEventListener('pointermove', (e) => {
  if (!drag || e.pointerId !== drag.id) return;
  const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
  if (!drag.moved) {
    if (Math.hypot(dx, dy) < 5) return;
    drag.moved = true;
    stage.setPointerCapture(e.pointerId);
    root.setAttribute('data-drag', '');
  }
  let p = drag.p0 - dx / (drag.w * 0.3) + dy / (drag.w * 0.17);
  /* rubber band past the ends */
  if (p < 0) p = -0.45 * (1 - Math.exp(p / 0.45));
  if (p > N - 1) p = N - 1 + 0.45 * (1 - Math.exp(-(p - N + 1) / 0.45));
  writePos(p);
  const now = performance.now();
  drag.hist.push([now, p]);
  while (drag.hist.length > 2 && now - drag.hist[0][0] > 90) drag.hist.shift();
  const r = Math.round(Math.max(0, Math.min(N - 1, p)));
  if (r !== active) { active = r; show(r, true); }
});
function release(e) {
  if (!drag || e.pointerId !== drag.id) return;
  const d = drag; drag = null;
  if (!d.moved) {
    const c = e.target.closest('.fxd-helix__card');
    if (c && e.type === 'pointerup') go(cards.indexOf(c));
    return;
  }
  root.removeAttribute('data-drag');
  const [t0, p0] = d.hist[0], [t1, p1] = d.hist[d.hist.length - 1];
  const v = t1 > t0 ? (p1 - p0) / ((t1 - t0) / 1000) : 0;
  go(Math.round(pos + Math.max(-4, Math.min(4, v * 0.22))));
  stage.focus({ preventScroll: true });
}
stage.addEventListener('pointerup', release);
stage.addEventListener('pointercancel', release);

/* pause the idle sway while the card is off screen */
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  root.toggleAttribute('data-off', !entries[0].isIntersecting);
});
io.observe(root);

css:
/* Focus distance and blur strength are registered numbers, so a single
   transition on the root racks focus through every layer at once: each
   layer computes its own |z − focus| and blurs by it. */
@property --fxd-diorama-focus { syntax: "<number>"; inherits: true; initial-value: 2; }
@property --fxd-diorama-bokeh { syntax: "<number>"; inherits: true; initial-value: 2.6; }

.fxd-diorama {
  /* Re-theme with these four. */
  --fxd-diorama-paper: oklch(0.955 0.024 82);
  --fxd-diorama-sun: oklch(0.82 0.135 60);
  --fxd-diorama-far: oklch(0.79 0.048 238);
  --fxd-diorama-near: oklch(0.37 0.07 162);

  --fxd-diorama-mat: color-mix(in oklch, var(--fxd-diorama-paper) 88%, var(--fxd-diorama-near));
  --fxd-diorama-ink: color-mix(in oklch, var(--fxd-diorama-near) 82%, black);
  --fxd-diorama-muted: color-mix(in oklch, var(--fxd-diorama-ink) 60%, var(--fxd-diorama-paper));
  --fxd-diorama-line: color-mix(in oklch, var(--fxd-diorama-ink) 16%, transparent);
  --fxd-diorama-ox: 0%;
  --fxd-diorama-oy: 0%;

  container-type: inline-size;
  display: grid;
  gap: 10px;
  box-sizing: border-box;
  inline-size: 100%;
  margin: 0;
  padding: 10px 10px 12px;
  border-radius: 18px;
  background: var(--fxd-diorama-mat);
  color: var(--fxd-diorama-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxd-diorama-line);
  transition: --fxd-diorama-focus 1.15s cubic-bezier(.65, 0, .25, 1), --fxd-diorama-bokeh .7s cubic-bezier(.3, 0, .2, 1);

  &[data-scrub] { transition: --fxd-diorama-focus .14s linear, --fxd-diorama-bokeh .7s cubic-bezier(.3, 0, .2, 1); }

  /* ── the box ── */
  & .fxd-diorama__box {
    position: relative;
    aspect-ratio: 16 / 10;
    min-block-size: 158px;
    max-block-size: 300px;
    border-radius: 10px;
    overflow: hidden;
    isolation: isolate;
    background: var(--fxd-diorama-paper);
    cursor: crosshair;
    touch-action: pan-y;
  }
  /* the recess of the shadow box, drawn over the scene */
  & .fxd-diorama__box::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 3;
    border-radius: inherit;
    pointer-events: none;
    box-shadow:
      inset 0 0 0 1px color-mix(in oklch, var(--fxd-diorama-ink) 18%, transparent),
      inset 0 2.4cqi 3.2cqi -1.6cqi color-mix(in oklch, var(--fxd-diorama-ink) 42%, transparent),
      inset 1.6cqi 0 2.4cqi -1.8cqi color-mix(in oklch, var(--fxd-diorama-ink) 22%, transparent),
      inset -1.6cqi 0 2.4cqi -1.8cqi color-mix(in oklch, var(--fxd-diorama-ink) 22%, transparent);
  }
  & .fxd-diorama__scene {
    position: absolute;
    inset: 0;
    perspective: 90cqi;
    perspective-origin: calc(50% + var(--fxd-diorama-ox)) calc(46% + var(--fxd-diorama-oy));
  }

  & .fxd-diorama__layer {
    --dz: max(calc(var(--z) - var(--fxd-diorama-focus)), calc(var(--fxd-diorama-focus) - var(--z)));
    --o: calc(var(--z) * 2.6% + 3%);
    position: absolute;
    inset: calc(var(--o) * -1) auto auto calc(var(--o) * -1);
    display: block;
    inline-size: calc(100% + 2 * var(--o));
    block-size: calc(100% + 2 * var(--o));
    fill: color-mix(in oklch, var(--fxd-diorama-far) calc(var(--t) * 100%), var(--fxd-diorama-near));
    transform: translateZ(calc(var(--z) * -9cqi)) scale(calc(1 + var(--z) * .1));
    filter:
      drop-shadow(0 .5cqi .8cqi color-mix(in oklch, var(--fxd-diorama-ink) 34%, transparent))
      blur(calc(var(--dz) * var(--fxd-diorama-bokeh) * .3cqi));
    pointer-events: none;
  }
  & svg.fxd-diorama__layer { overflow: visible; }
  & .fxd-diorama__layer path,
  & .fxd-diorama__layer rect,
  & .fxd-diorama__layer--sky { pointer-events: auto; }
  & .fxd-diorama__layer path { stroke: color-mix(in oklch, var(--fxd-diorama-paper) 30%, transparent); stroke-width: .6; }

  & .fxd-diorama__layer--sky {
    filter: blur(calc(var(--dz) * var(--fxd-diorama-bokeh) * .3cqi));
    background:
      radial-gradient(60% 55% at 60% 58%, color-mix(in oklch, var(--fxd-diorama-sun) 55%, var(--fxd-diorama-paper)) 0%, transparent 70%),
      linear-gradient(color-mix(in oklch, var(--fxd-diorama-far) 45%, var(--fxd-diorama-paper)) 0%, var(--fxd-diorama-paper) 62%);
  }
  & .fxd-diorama__sun {
    position: absolute;
    left: 58%;
    top: 37%;
    inline-size: 15%;
    aspect-ratio: 1;
    border-radius: 50%;
    background: radial-gradient(circle at 45% 40%, color-mix(in oklch, var(--fxd-diorama-sun) 60%, white), var(--fxd-diorama-sun) 70%);
    box-shadow: 0 0 0 1.4cqi color-mix(in oklch, var(--fxd-diorama-sun) 22%, transparent);
  }
  & .fxd-diorama__clouds {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    fill: color-mix(in oklch, var(--fxd-diorama-paper) 80%, white);
    filter: drop-shadow(0 .4cqi .5cqi color-mix(in oklch, var(--fxd-diorama-far) 60%, transparent));
    animation: fxd-diorama-drift 38s cubic-bezier(.45, 0, .55, 1) infinite alternate;
  }
  & .fxd-diorama__clouds path { stroke: none; pointer-events: none; }

  & .fxd-diorama__snow { fill: var(--fxd-diorama-paper); stroke: none; }
  & .fxd-diorama__tower { fill: var(--fxd-diorama-paper); }
  & .fxd-diorama__band { fill: color-mix(in oklch, var(--fxd-diorama-sun) 55%, oklch(0.55 0.17 30)); stroke: none; }
  & .fxd-diorama__lantern { fill: color-mix(in oklch, var(--fxd-diorama-sun) 70%, white); }
  & .fxd-diorama__flash {
    fill: color-mix(in oklch, var(--fxd-diorama-sun) 75%, white);
    opacity: .22;
    pointer-events: none;
    transform-box: fill-box;
    transform-origin: center;
    animation: fxd-diorama-flash 5s linear infinite;
  }

  & .fxd-diorama__layer--sea { fill: color-mix(in oklch, var(--fxd-diorama-far) 78%, var(--fxd-diorama-paper)); }
  & .fxd-diorama__glint { fill: color-mix(in oklch, var(--fxd-diorama-sun) 50%, white); stroke: none; opacity: .85; }
  & .fxd-diorama__wave { fill: color-mix(in oklch, var(--fxd-diorama-paper) 55%, var(--fxd-diorama-far)); stroke: none; opacity: .8; }
  /* dry reeds: straw, so the nearest plane separates from the pine bank */
  & .fxd-diorama__layer--reeds { fill: color-mix(in oklch, var(--fxd-diorama-sun) 42%, oklch(0.5 0.07 95)); }
  & .fxd-diorama__boat {
    fill: color-mix(in oklch, var(--fxd-diorama-near) 70%, var(--fxd-diorama-far));
    transform-box: fill-box;
    transform-origin: 50% 92%;
    animation: fxd-diorama-bob 4.6s cubic-bezier(.45, 0, .55, 1) infinite;
  }
  & .fxd-diorama__sail { fill: var(--fxd-diorama-paper); }
  & .fxd-diorama__mast { fill: none; stroke: color-mix(in oklch, var(--fxd-diorama-near) 70%, var(--fxd-diorama-far)); stroke-width: 1.4; }
  & .fxd-diorama__heads rect { fill: color-mix(in oklch, var(--fxd-diorama-ink) 60%, oklch(0.45 0.09 45)); stroke: none; }

  /* tap-to-focus reticle */
  & .fxd-diorama__af {
    position: absolute;
    z-index: 4;
    left: 0;
    top: 0;
    inline-size: 12cqi;
    max-inline-size: 52px;
    aspect-ratio: 1;
    translate: -50% -50%;
    opacity: 0;
    pointer-events: none;
    background:
      linear-gradient(var(--fxd-diorama-sun), var(--fxd-diorama-sun)) 0 0 / 22% 2px,
      linear-gradient(var(--fxd-diorama-sun), var(--fxd-diorama-sun)) 0 0 / 2px 22%,
      linear-gradient(var(--fxd-diorama-sun), var(--fxd-diorama-sun)) 100% 0 / 22% 2px,
      linear-gradient(var(--fxd-diorama-sun), var(--fxd-diorama-sun)) 100% 0 / 2px 22%,
      linear-gradient(var(--fxd-diorama-sun), var(--fxd-diorama-sun)) 0 100% / 22% 2px,
      linear-gradient(var(--fxd-diorama-sun), var(--fxd-diorama-sun)) 0 100% / 2px 22%,
      linear-gradient(var(--fxd-diorama-sun), var(--fxd-diorama-sun)) 100% 100% / 22% 2px,
      linear-gradient(var(--fxd-diorama-sun), var(--fxd-diorama-sun)) 100% 100% / 2px 22%;
    background-repeat: no-repeat;
    filter: drop-shadow(0 0 1px color-mix(in oklch, var(--fxd-diorama-ink) 70%, transparent));
  }

  & .fxd-diorama__hint {
    position: absolute;
    z-index: 2;
    right: clamp(8px, 2.6cqi, 12px);
    bottom: clamp(8px, 2.6cqi, 12px);
    padding: 3px 8px;
    border-radius: 999px;
    background: color-mix(in oklch, var(--fxd-diorama-paper) 72%, transparent);
    backdrop-filter: blur(4px);
    font-size: 10.5px;
    font-weight: 600;
    color: var(--fxd-diorama-ink);
    pointer-events: none;
    transition: opacity .4s;
  }
  &[data-touched] .fxd-diorama__hint { opacity: 0; }

  & .fxd-diorama__cap {
    position: absolute;
    z-index: 2;
    inset: 0 auto auto 0;
    display: grid;
    gap: 2px;
    padding: clamp(10px, 3.6cqi, 16px);
    pointer-events: none;
  }
  & .fxd-diorama__eyebrow {
    font-size: clamp(9px, 2.5cqi, 11px);
    font-weight: 650;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--fxd-diorama-muted);
  }
  & .fxd-diorama__title {
    font-size: clamp(15px, 5.4cqi, 22px);
    font-weight: 700;
    letter-spacing: -.015em;
    line-height: 1.1;
    text-wrap: balance;
  }

  /* ── controls ── */
  & .fxd-diorama__controls {
    display: grid;
    grid-template-areas: "read ap" "scale scale";
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 6px 10px;
    padding-inline: 4px;
  }
  & .fxd-diorama__read {
    grid-area: read;
    display: flex;
    align-items: baseline;
    gap: 6px;
    margin: 0;
    min-inline-size: 0;
    white-space: nowrap;
    font-size: 12px;
  }
  & .fxd-diorama__k {
    font-size: 10px;
    font-weight: 650;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--fxd-diorama-muted);
  }
  & .fxd-diorama__read b {
    font: 600 13px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxd-diorama__read [data-k="name"] {
    overflow: hidden;
    text-overflow: ellipsis;
    color: var(--fxd-diorama-muted);
  }

  & .fxd-diorama__ap {
    grid-area: ap;
    display: flex;
    gap: 2px;
    margin: 0;
    padding: 2px;
    border: 0;
    border-radius: 999px;
    background: color-mix(in oklch, var(--fxd-diorama-ink) 8%, transparent);
  }
  & .fxd-diorama__ap label { position: relative; display: grid; cursor: pointer; }
  & .fxd-diorama__ap input {
    position: absolute;
    inset: 0;
    margin: 0;
    opacity: 0;
    cursor: pointer;
  }
  & .fxd-diorama__ap span {
    padding: 4px 8px;
    border-radius: 999px;
    font: 600 11px/1.2 ui-monospace, Menlo, monospace;
    color: var(--fxd-diorama-muted);
    transition: background-color .25s, color .25s, box-shadow .25s;
  }
  & .fxd-diorama__ap label:hover span { color: var(--fxd-diorama-ink); }
  & .fxd-diorama__ap label:has(:checked) span {
    background: var(--fxd-diorama-paper);
    color: var(--fxd-diorama-ink);
    box-shadow: 0 1px 2px color-mix(in oklch, var(--fxd-diorama-ink) 22%, transparent);
  }
  & .fxd-diorama__ap label:has(:focus-visible) span { outline: 2px solid var(--fxd-diorama-near); outline-offset: 1px; }

  & .fxd-diorama__scale {
    --thumb: 14px;
    grid-area: scale;
    position: relative;
    display: grid;
    padding-block-end: 14px;
  }
  & .fxd-diorama__range {
    appearance: none;
    -webkit-appearance: none;
    inline-size: 100%;
    block-size: 22px;
    margin: 0;
    background:
      repeating-linear-gradient(90deg, var(--fxd-diorama-line) 0 1px, transparent 1px calc((100% - var(--thumb)) / 25)) calc(var(--thumb) / 2) 60% / calc(100% - var(--thumb) + 1px) 6px no-repeat,
      linear-gradient(var(--fxd-diorama-line), var(--fxd-diorama-line)) 0 100% / 100% 1px no-repeat;
    accent-color: var(--fxd-diorama-near);
    cursor: ew-resize;
  }
  & .fxd-diorama__range::-webkit-slider-thumb {
    -webkit-appearance: none;
    inline-size: var(--thumb);
    block-size: 22px;
    border: 0;
    background:
      linear-gradient(var(--fxd-diorama-near), var(--fxd-diorama-near)) 50% 0 / 2px 100% no-repeat,
      conic-gradient(from 150deg at 50% 0, var(--fxd-diorama-near) 0 60deg, transparent 0) 0 0 / 100% 8px no-repeat;
  }
  & .fxd-diorama__range::-moz-range-thumb {
    inline-size: var(--thumb);
    block-size: 22px;
    border: 0;
    border-radius: 0;
    background:
      linear-gradient(var(--fxd-diorama-near), var(--fxd-diorama-near)) 50% 0 / 2px 100% no-repeat,
      conic-gradient(from 150deg at 50% 0, var(--fxd-diorama-near) 0 60deg, transparent 0) 0 0 / 100% 8px no-repeat;
  }
  & .fxd-diorama__range:focus-visible { outline: 2px solid var(--fxd-diorama-near); outline-offset: 3px; border-radius: 3px; }
  & .fxd-diorama__ticks {
    position: absolute;
    inset: auto 0 0;
    block-size: 12px;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  & .fxd-diorama__ticks li {
    position: absolute;
    left: calc(var(--thumb) / 2 + (100% - var(--thumb)) * var(--z) / 5);
    translate: -50% 0;
    font: 500 10px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxd-diorama-muted);
  }
  & .fxd-diorama__ticks li::before {
    content: "";
    position: absolute;
    left: 50%;
    bottom: calc(100% + 3px);
    inline-size: 1px;
    block-size: 8px;
    background: var(--fxd-diorama-muted);
  }
  @container (max-width: 330px) {
    & .fxd-diorama__k { display: none; }
    & .fxd-diorama__ap span { padding-inline: 6px; }
  }
  & .fxd-diorama__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  &[data-off] .fxd-diorama__clouds,
  &[data-off] .fxd-diorama__boat,
  &[data-off] .fxd-diorama__flash { animation-play-state: paused; }
}

@keyframes fxd-diorama-drift {
  from { translate: -5% 0; }
  to { translate: 6% 0; }
}
@keyframes fxd-diorama-bob {
  0%, 100% { rotate: -2.5deg; translate: 0 0; }
  50% { rotate: 2deg; translate: 0 .8px; }
}
/* Fl W 5s: one short flash every five seconds */
@keyframes fxd-diorama-flash {
  0%, 84%, 100% { opacity: .2; scale: .7; }
  89% { opacity: 1; scale: 1.25; }
}

@media (prefers-reduced-motion: reduce) {
  .fxd-diorama,
  .fxd-diorama[data-scrub] { transition: none; }
  .fxd-diorama .fxd-diorama__clouds,
  .fxd-diorama .fxd-diorama__boat,
  .fxd-diorama .fxd-diorama__flash { animation: none; }
  .fxd-diorama .fxd-diorama__flash { opacity: .5; }
}

js:
/* Paper diorama. Two things move here:
   1. Head-coupled perspective — the pointer moves perspective-origin, not the
      layers. The frame stays put and deeper layers slide further, exactly
      like looking into a shadow box from a different spot.
   2. Rack focus — --fxd-diorama-focus is a registered number; CSS blurs each
      layer by |z − focus| × aperture, and the root transition pulls focus. */
const box = root.querySelector('.fxd-diorama__box');
const range = root.querySelector('.fxd-diorama__range');
const distEl = root.querySelector('[data-k="dist"]');
const nameEl = root.querySelector('[data-k="name"]');
const af = root.querySelector('.fxd-diorama__af');
const radios = [...root.querySelectorAll('.fxd-diorama__ap input')];
const calm = matchMedia('(prefers-reduced-motion: reduce)');

const DIST = [12, 20, 28, 36, 44, 64];          /* cm from the glass to each plane */
const NAMES = ['Reeds', 'Pines', 'Boat', 'Lighthouse', 'Ridge', 'Sky'];
const uid = Math.random().toString(36).slice(2, 8);
radios.forEach((r) => { r.name = 'fxd-diorama-ap-' + uid; });

function describe(v) {
  const i = Math.min(4, Math.floor(v)), k = v - i;
  const cm = v >= 4.9 ? '∞' : Math.round(DIST[i] + (DIST[i + 1] - DIST[i]) * k) + ' cm';
  const near = Math.round(v);
  const name = Math.abs(v - near) < 0.18 ? NAMES[near] : NAMES[Math.floor(v)] + ' – ' + NAMES[Math.ceil(v)];
  return { cm, name };
}

function setFocus(v, scrub) {
  v = Math.max(0, Math.min(5, v));
  root.toggleAttribute('data-scrub', !!scrub);
  root.style.setProperty('--fxd-diorama-focus', v.toFixed(3));
  if (String(range.value) !== String(v)) range.value = v;
  const d = describe(v);
  distEl.textContent = d.cm;
  nameEl.textContent = d.name;
  range.setAttribute('aria-valuetext', d.cm + ', ' + d.name + ' sharp');
}
setFocus(parseFloat(range.value), false);

range.addEventListener('input', () => setFocus(parseFloat(range.value), true));
range.addEventListener('change', () => root.removeAttribute('data-scrub'));

radios.forEach((r) => r.addEventListener('change', () => {
  if (r.checked) root.style.setProperty('--fxd-diorama-bokeh', r.value);
}));

/* tap a paper layer to pull focus onto it */
let down = null;
box.addEventListener('pointerdown', (e) => { down = { x: e.clientX, y: e.clientY }; });
box.addEventListener('pointerup', (e) => {
  if (!down || Math.hypot(e.clientX - down.x, e.clientY - down.y) > 6) { down = null; return; }
  down = null;
  const hit = e.target.closest('[data-z]');
  if (!hit) return;
  setFocus(Number(hit.dataset.z), false);
  root.setAttribute('data-touched', '');
  const r = box.getBoundingClientRect();
  af.style.left = (e.clientX - r.left) + 'px';
  af.style.top = (e.clientY - r.top) + 'px';
  af.getAnimations().forEach((a) => a.cancel());
  af.animate(
    calm.matches
      ? [{ opacity: 1 }, { opacity: 1, offset: .7 }, { opacity: 0 }]
      : [{ opacity: 0, scale: 1.45 }, { opacity: 1, scale: 1, offset: .18 }, { opacity: 1, scale: 1, offset: .55 }, { opacity: 1, scale: .92, offset: .62 }, { opacity: 0, scale: .92 }],
    { duration: 1300, easing: 'cubic-bezier(.2,.8,.2,1)' }
  );
});

/* ── head-coupled perspective ── */
let tx = 0, ty = 0, cx = 0, cy = 0, lastMove = -1e9, raf = 0, last = 0, seen = false;
box.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'touch') return;
  const r = box.getBoundingClientRect();
  tx = ((e.clientX - r.left) / r.width - 0.5) * 2;
  ty = ((e.clientY - r.top) / r.height - 0.5) * 2;
  lastMove = performance.now();
  kick();
});
box.addEventListener('pointerleave', () => { lastMove = performance.now() - 900; });

function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = Math.min(0.05, (now - (last || now)) / 1000);
  last = now;
  const t = now / 1000;
  /* at rest the viewer drifts on a slow Lissajous, so the box never looks frozen */
  const idle = now - lastMove > 1200;
  const gx = idle ? Math.sin(t * 0.31) * 0.55 : tx;
  const gy = idle ? Math.sin(t * 0.23 + 1.2) * 0.35 : ty;
  const k = 1 - Math.exp(-dt * (idle ? 1.6 : 7));
  cx += (gx - cx) * k;
  cy += (gy - cy) * k;
  root.style.setProperty('--fxd-diorama-ox', (cx * 32).toFixed(2) + '%');
  root.style.setProperty('--fxd-diorama-oy', (cy * 20).toFixed(2) + '%');
  if (seen && !calm.matches) raf = requestAnimationFrame(frame);
}
function kick() {
  if (!raf && seen && !calm.matches) { last = 0; raf = requestAnimationFrame(frame); }
}

const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  seen = entries[0].isIntersecting;
  root.toggleAttribute('data-off', !seen);
  if (seen) kick();
});
io.observe(root);

calm.addEventListener('change', function onCalm() {
  if (!root.isConnected) { calm.removeEventListener('change', onCalm); return; }
  if (calm.matches) {
    root.style.setProperty('--fxd-diorama-ox', '0%');
    root.style.setProperty('--fxd-diorama-oy', '0%');
  } else kick();
});

css:
/* One registered progress value folds the whole carton. Each hinge maps it
   through its own clamp() window — walls staggered by --i, then the base,
   then the tuck flap — so a single transition plays the sequence and the
   scrubber can stop it anywhere. */
@property --fxd-dieline-p { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --fxd-dieline-yaw { syntax: "<angle>"; inherits: true; initial-value: -28deg; }
@property --fxd-dieline-tilt { syntax: "<angle>"; inherits: true; initial-value: 54deg; }
@property --fxd-dieline-sway { syntax: "<angle>"; inherits: true; initial-value: 0deg; }

.fxd-dieline {
  /* Re-theme with these four. */
  --fxd-dieline-desk: oklch(0.955 0.008 95);
  --fxd-dieline-mat: oklch(0.6 0.085 162);
  --fxd-dieline-board: oklch(0.76 0.07 70);
  --fxd-dieline-ink: oklch(0.29 0.04 45);

  --fxd-dieline-red: color-mix(in oklch, oklch(0.56 0.17 32) 85%, var(--fxd-dieline-board));
  --fxd-dieline-inner: color-mix(in oklch, var(--fxd-dieline-board) 72%, white);
  --fxd-dieline-muted: color-mix(in oklch, var(--fxd-dieline-ink) 60%, var(--fxd-dieline-desk));
  --fxd-dieline-line: color-mix(in oklch, var(--fxd-dieline-ink) 14%, transparent);
  --fxd-dieline-grid: color-mix(in oklch, white 22%, transparent);
  --fxd-dieline-spring: linear(0, 0.009, 0.035 2.1%, 0.141, 0.281 6.7%, 0.723 12.9%, 0.938 16.7%, 1.017, 1.077, 1.121, 1.149 24.3%, 1.159, 1.163, 1.161, 1.154 29.9%, 1.129 32.8%, 1.051 39.6%, 1.017 43.1%, 0.991, 0.977 51%, 0.974 53.8%, 0.975 57.1%, 0.997 69.8%, 1.003 76.9%, 1);

  /* every size is in board millimetres: the mat grid, the net and the spec agree */
  --mm: .2875cqi;
  --cw: calc(96 * var(--mm));
  --cd: calc(66 * var(--mm));
  --ch: calc(51 * var(--mm));
  --ct: calc(18 * var(--mm));
  --lift: sin(calc(clamp(0, calc(var(--fxd-dieline-p) / .46), 1) * 90deg));
  /* while the long back, base and tuck chain swings under the carton, the
     camera rises with it: the mat drops away by up to two wall heights and
     comes back up to meet the finished carton */
  --rise: calc(2 * sin(calc(clamp(0, calc(var(--fxd-dieline-p) / .8), 1) * 180deg)));

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "stage" "bar" "spec";
  gap: 10px;
  box-sizing: border-box;
  inline-size: 100%;
  padding: 10px 10px 12px;
  border-radius: 18px;
  background: var(--fxd-dieline-desk);
  color: var(--fxd-dieline-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxd-dieline-line);
  transition:
    --fxd-dieline-p .16s linear,
    --fxd-dieline-yaw .7s var(--fxd-dieline-spring),
    --fxd-dieline-tilt .7s var(--fxd-dieline-spring);

  &[data-anim] { transition: --fxd-dieline-p 2.4s cubic-bezier(.5, .05, .25, 1), --fxd-dieline-yaw .7s var(--fxd-dieline-spring), --fxd-dieline-tilt .7s var(--fxd-dieline-spring); }
  &[data-drag] { transition: --fxd-dieline-p .16s linear; }

  /* ── stage and camera ── */
  & .fxd-dieline__stage {
    grid-area: stage;
    position: relative;
    block-size: clamp(200px, 74cqi, 300px);
    border-radius: 12px;
    overflow: hidden;
    perspective: 170cqi;
    perspective-origin: 50% 30%;
    background: color-mix(in oklch, var(--fxd-dieline-mat) 86%, black);
    cursor: grab;
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
    outline: none;
  }
  &[data-drag] .fxd-dieline__stage { cursor: grabbing; }
  & .fxd-dieline__stage:focus-visible { box-shadow: 0 0 0 2px var(--fxd-dieline-desk), 0 0 0 4px var(--fxd-dieline-ink); }
  & .fxd-dieline__orbit {
    position: absolute;
    left: 50%;
    top: 52%;
    transform-style: preserve-3d;
    /* the camera dollies in as the carton closes */
    transform: translateZ(calc(var(--lift) * 18cqi)) rotateX(var(--fxd-dieline-tilt)) rotateZ(calc(var(--fxd-dieline-yaw) + var(--fxd-dieline-sway)));
    animation: fxd-dieline-sway 12s cubic-bezier(.45, 0, .55, 1) infinite alternate;
  }
  &[data-drag] .fxd-dieline__orbit,
  &[data-off] .fxd-dieline__orbit { animation-play-state: paused; }

  /* self-healing cutting mat: 10 mm minor grid, 50 mm major */
  & .fxd-dieline__mat {
    position: absolute;
    left: calc(-350 * var(--mm));
    top: calc(-350 * var(--mm));
    inline-size: calc(700 * var(--mm));
    block-size: calc(700 * var(--mm));
    transform: translateZ(calc(-1px - var(--rise) * var(--ch)));
    background:
      linear-gradient(90deg, var(--fxd-dieline-grid) 1px, transparent 1px) 0 0 / calc(50 * var(--mm)) calc(50 * var(--mm)),
      linear-gradient(var(--fxd-dieline-grid) 1px, transparent 1px) 0 0 / calc(50 * var(--mm)) calc(50 * var(--mm)),
      linear-gradient(90deg, color-mix(in oklch, white 9%, transparent) 1px, transparent 1px) 0 0 / calc(10 * var(--mm)) calc(10 * var(--mm)),
      linear-gradient(color-mix(in oklch, white 9%, transparent) 1px, transparent 1px) 0 0 / calc(10 * var(--mm)) calc(10 * var(--mm)),
      var(--fxd-dieline-mat);
    mask-image: radial-gradient(closest-side, #000 50%, transparent);
  }
  & .fxd-dieline__shadow {
    position: absolute;
    left: calc(var(--cw) / -2);
    top: calc(var(--cd) / -2);
    inline-size: var(--cw);
    block-size: var(--cd);
    border-radius: 1cqi;
    background: color-mix(in oklch, black 70%, var(--fxd-dieline-mat));
    transform: translateY(calc((var(--cd) + var(--ct)) / 2 * (1 - var(--lift)))) translateZ(calc(.5px - var(--rise) * var(--ch))) scale(calc(1 + var(--lift) * .1 + var(--rise) * .12));
    filter: blur(calc(1cqi + (var(--lift) + var(--rise)) * 2cqi));
    opacity: calc(var(--lift) * .6 / (1 + var(--rise)));
  }

  /* ── panels ── */
  & .fxd-dieline__panel {
    position: absolute;
    transform-style: preserve-3d;
  }
  & .fxd-dieline__face,
  & .fxd-dieline__in {
    position: absolute;
    inset: 0;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
  }
  & .fxd-dieline__face {
    overflow: hidden;
    background:
      radial-gradient(120% 90% at 30% 20%, color-mix(in oklch, var(--fxd-dieline-board) 88%, white), transparent 70%),
      var(--fxd-dieline-board);
    box-shadow: inset 0 0 0 .5px color-mix(in oklch, var(--fxd-dieline-ink) 45%, transparent);
    filter: brightness(calc(1 - (1 - var(--shade, 1)) * sin(calc(var(--k, 0) * 90deg))));
  }
  & .fxd-dieline__in {
    transform: rotateY(180deg);
    background: var(--fxd-dieline-inner);
    box-shadow: inset 0 0 0 .5px color-mix(in oklch, var(--fxd-dieline-ink) 30%, transparent);
    filter: brightness(calc(.92 - (1 - var(--shade, 1)) * .5 * sin(calc(var(--k, 0) * 90deg))));
  }
  /* fold lines are dashed, and fade as soon as the board starts to bend */
  & .fxd-dieline__face::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    border: 0 dashed color-mix(in oklch, var(--fxd-dieline-ink) 70%, transparent);
    opacity: clamp(0, calc(1 - var(--fxd-dieline-p) * 5), 1);
    pointer-events: none;
  }

  & .fxd-dieline__top {
    left: calc(var(--cw) / -2);
    top: calc(var(--cd) / -2);
    inline-size: var(--cw);
    block-size: var(--cd);
    transform: translateY(calc((var(--cd) + var(--ct)) / 2 * (1 - var(--lift)))) translateZ(calc(var(--ch) * var(--lift)));
  }
  & .fxd-dieline__front,
  & .fxd-dieline__back,
  & .fxd-dieline__left,
  & .fxd-dieline__right {
    --k: clamp(0, calc((var(--fxd-dieline-p) - var(--i) * .06) / .42), 1);
  }
  & .fxd-dieline__front {
    --shade: .9;
    left: 0;
    top: 100%;
    inline-size: var(--cw);
    block-size: var(--ch);
    transform-origin: 50% 0;
    transform: rotateX(calc(var(--k) * -90deg));
  }
  & .fxd-dieline__front > .fxd-dieline__face::before { border-top-width: 1px; }
  & .fxd-dieline__back {
    --shade: .7;
    left: 0;
    bottom: 100%;
    inline-size: var(--cw);
    block-size: var(--ch);
    transform-origin: 50% 100%;
    transform: rotateX(calc(var(--k) * 90deg));
  }
  & .fxd-dieline__back > .fxd-dieline__face::before { border-bottom-width: 1px; }
  & .fxd-dieline__left {
    --shade: .97;
    right: 100%;
    top: 0;
    inline-size: var(--ch);
    block-size: var(--cd);
    transform-origin: 100% 50%;
    transform: rotateY(calc(var(--k) * -90deg));
  }
  & .fxd-dieline__left > .fxd-dieline__face::before { border-right-width: 1px; }
  & .fxd-dieline__right {
    --shade: .76;
    left: 100%;
    top: 0;
    inline-size: var(--ch);
    block-size: var(--cd);
    transform-origin: 0 50%;
    transform: rotateY(calc(var(--k) * 90deg));
  }
  & .fxd-dieline__right > .fxd-dieline__face::before { border-left-width: 1px; }
  & .fxd-dieline__bottom {
    --k: clamp(0, calc((var(--fxd-dieline-p) - .52) / .26), 1);
    --shade: .6;
    left: 0;
    bottom: 100%;
    inline-size: var(--cw);
    block-size: var(--cd);
    transform-origin: 50% 100%;
    transform: rotateX(calc(var(--k) * 90deg));
  }
  & .fxd-dieline__bottom > .fxd-dieline__face::before { border-bottom-width: 1px; }
  & .fxd-dieline__tuck {
    --k: clamp(0, calc((var(--fxd-dieline-p) - .72) / .24), 1);
    --shade: .8;
    left: 0;
    bottom: 100%;
    inline-size: var(--cw);
    block-size: var(--ct);
    transform-origin: 50% 100%;
    /* a few degrees past square, so the flap tucks inside the front wall */
    transform: rotateX(calc(var(--k) * 95deg));
  }
  & .fxd-dieline__tuck > .fxd-dieline__face::before { border-bottom-width: 1px; }
  /* the thumb notch and rounded tuck corners are die cuts */
  & .fxd-dieline__tuck > .fxd-dieline__face,
  & .fxd-dieline__tuck > .fxd-dieline__in {
    border-radius: 2.4cqi 2.4cqi 0 0;
    mask-image: radial-gradient(circle at 50% 0, transparent 2.6cqi, #000 calc(2.6cqi + .5px));
  }

  /* ── print ── */
  & .fxd-dieline__print {
    position: absolute;
    inset: 0;
    display: grid;
    place-content: center;
    justify-items: center;
    text-align: center;
    color: var(--fxd-dieline-ink);
  }
  & .fxd-dieline__print--top { gap: .5cqi; }
  & .fxd-dieline__kettle {
    inline-size: 5.4cqi;
    block-size: 5.4cqi;
    fill: none;
    stroke: var(--fxd-dieline-red);
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxd-dieline__brand {
    font-size: 1.7cqi;
    font-weight: 700;
    letter-spacing: .26em;
    text-transform: uppercase;
  }
  & .fxd-dieline__name {
    font-size: 3.5cqi;
    font-weight: 800;
    letter-spacing: -.02em;
    line-height: 1;
    color: var(--fxd-dieline-red);
  }
  & .fxd-dieline__sub {
    font-size: 1.45cqi;
    font-weight: 600;
    letter-spacing: .06em;
    font-variant-numeric: tabular-nums;
    text-transform: uppercase;
  }
  & .fxd-dieline__print--front {
    gap: 1.4cqi;
    background: linear-gradient(var(--fxd-dieline-red), var(--fxd-dieline-red)) 0 100% / 100% 1.2cqi no-repeat;
  }
  & .fxd-dieline__line { font-size: 2cqi; font-weight: 700; letter-spacing: .02em; }
  & .fxd-dieline__steep {
    display: flex;
    gap: 2.6cqi;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  & .fxd-dieline__steep li {
    display: grid;
    justify-items: center;
    gap: .3cqi;
    font-size: 1.5cqi;
    font-weight: 700;
    font-variant-numeric: tabular-nums;
  }
  & .fxd-dieline__steep svg,
  & .fxd-dieline__print--bottom svg {
    inline-size: 3.6cqi;
    block-size: 3.6cqi;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  /* the back folds the other way, so its print is set upside down on the net */
  & .fxd-dieline__print--back {
    rotate: 180deg;
    gap: 1cqi;
    padding: 1.6cqi;
    font-size: 1.25cqi;
    line-height: 1.35;
    font-weight: 600;
  }
  & .fxd-dieline__bars { inline-size: 14cqi; block-size: 4.6cqi; fill: var(--fxd-dieline-ink); }
  /* side panels hinge on a vertical edge: print runs along the hinge */
  & .fxd-dieline__print--side {
    inset: auto;
    left: 50%;
    top: 50%;
    inline-size: var(--cd);
    block-size: var(--ch);
    translate: -50% -50%;
    rotate: -90deg;
    gap: .4cqi;
    background: repeating-linear-gradient(135deg, transparent 0 1.1cqi, color-mix(in oklch, var(--fxd-dieline-red) 30%, transparent) 1.1cqi 1.5cqi);
  }
  & .fxd-dieline__print--l { rotate: 90deg; }
  & .fxd-dieline__print--side span {
    padding: .3cqi 1cqi;
    background: var(--fxd-dieline-board);
    font-size: 3cqi;
    font-weight: 800;
    letter-spacing: -.02em;
    color: var(--fxd-dieline-red);
  }
  & .fxd-dieline__print--side i {
    padding: 0 .8cqi;
    background: var(--fxd-dieline-board);
    font-size: 1.3cqi;
    font-style: normal;
    font-weight: 700;
    letter-spacing: .14em;
    text-transform: uppercase;
  }
  & .fxd-dieline__print--bottom {
    rotate: 180deg;
    gap: .8cqi;
    font-size: 1.3cqi;
    font-weight: 600;
    color: color-mix(in oklch, var(--fxd-dieline-ink) 75%, var(--fxd-dieline-board));
  }

  /* ── overlay header ── */
  & .fxd-dieline__head {
    position: absolute;
    left: 22px;
    top: 20px;
    pointer-events: none;
    color: oklch(0.98 0.01 95);
  }
  & .fxd-dieline__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .08em;
    text-transform: uppercase;
    opacity: .78;
  }
  & .fxd-dieline__title {
    margin: 2px 0 0;
    font-size: clamp(15px, 5cqi, 20px);
    font-weight: 700;
    letter-spacing: -.01em;
    text-wrap: balance;
  }

  /* ── controls ── */
  & .fxd-dieline__bar {
    grid-area: bar;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) 4.5ch;
    align-items: center;
    gap: 10px;
    padding-inline: 2px;
  }
  & .fxd-dieline__fold {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    min-inline-size: 92px;
    padding: 8px 14px 8px 11px;
    border: 0;
    border-radius: 999px;
    background: var(--fxd-dieline-ink);
    color: var(--fxd-dieline-desk);
    font: 650 13px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: background-color .2s, scale .4s var(--fxd-dieline-spring);
  }
  & .fxd-dieline__fold:hover { background: color-mix(in oklch, var(--fxd-dieline-ink) 82%, var(--fxd-dieline-red)); }
  & .fxd-dieline__fold:active { scale: .95; }
  & .fxd-dieline__fold:focus-visible { outline: 2px solid var(--fxd-dieline-red); outline-offset: 2px; }
  & .fxd-dieline__fold svg {
    inline-size: 16px;
    block-size: 16px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.3;
    stroke-linejoin: round;
    stroke-linecap: round;
  }
  & .fxd-dieline__ic-flat { display: none; }
  & .fxd-dieline__fold[aria-pressed="true"] .fxd-dieline__ic-flat { display: inline; }
  & .fxd-dieline__fold[aria-pressed="true"] .fxd-dieline__ic-fold { display: none; }
  & .fxd-dieline__range {
    inline-size: 100%;
    margin: 0;
    accent-color: var(--fxd-dieline-red);
    cursor: ew-resize;
  }
  & .fxd-dieline__range:focus-visible { outline: 2px solid var(--fxd-dieline-ink); outline-offset: 2px; border-radius: 4px; }
  & .fxd-dieline__pct {
    text-align: end;
    font: 600 12px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxd-dieline__spec {
    grid-area: spec;
    display: flex;
    flex-wrap: wrap;
    gap: 2px 14px;
    margin: 0;
    padding-inline: 4px;
    font-size: 11.5px;
    color: var(--fxd-dieline-muted);
  }
  & .fxd-dieline__spec b {
    font-weight: 600;
    font-family: ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxd-dieline-ink);
  }
  & .fxd-dieline__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@keyframes fxd-dieline-sway {
  from { --fxd-dieline-sway: -7deg; }
  to { --fxd-dieline-sway: 7deg; }
}

@media (prefers-reduced-motion: reduce) {
  .fxd-dieline,
  .fxd-dieline[data-anim],
  .fxd-dieline[data-drag] { transition: none; }
  .fxd-dieline .fxd-dieline__orbit { animation: none; }
  .fxd-dieline .fxd-dieline__fold { transition: none; }
}

js:
/* Dieline fold. --fxd-dieline-p (0 = flat net, 1 = closed carton) is the
   only fold state; CSS maps it through each hinge's window. The button hands
   it to a long transition, the scrubber writes it directly, and while a
   transition runs we read the live value back so the scrubber and the
   percentage follow the board. Drag orbits the camera with inertia. */
const stage = root.querySelector('.fxd-dieline__stage');
const btn = root.querySelector('.fxd-dieline__fold');
const label = root.querySelector('[data-k="label"]');
const range = root.querySelector('.fxd-dieline__range');
const pct = root.querySelector('.fxd-dieline__pct');
const calm = matchMedia('(prefers-reduced-motion: reduce)');

let target = 0, yaw = -28, tilt = 54, vyaw = 0, vtilt = 0;
let syncing = 0, spin = 0, drag = null, autoFolded = false, seen = false;

function readP() {
  return parseFloat(getComputedStyle(root).getPropertyValue('--fxd-dieline-p')) || 0;
}
function paint(v) {
  const n = Math.round(v * 100);
  range.value = n;
  pct.textContent = n + '%';
  range.setAttribute('aria-valuetext', n === 0 ? 'Flat net' : n === 100 ? 'Closed carton' : n + '% folded');
}
function setButton() {
  const closed = target >= 0.5;
  btn.setAttribute('aria-pressed', closed ? 'true' : 'false');
  label.textContent = closed ? 'Flatten' : 'Fold';
}

/* follow a running transition so the controls never lie about the board */
function sync() {
  if (!root.isConnected) return;
  const v = readP();
  paint(v);
  if (Math.abs(v - target) > 0.002) syncing = requestAnimationFrame(sync);
  else { syncing = 0; paint(target); }
}

function fold(to, animate) {
  target = to;
  root.toggleAttribute('data-anim', !!animate && !calm.matches);
  root.style.setProperty('--fxd-dieline-p', to.toFixed(3));
  setButton();
  if (!animate || calm.matches) { paint(to); return; }
  cancelAnimationFrame(syncing);
  syncing = requestAnimationFrame(sync);
}

btn.addEventListener('click', () => { autoFolded = true; fold(target >= 0.5 ? 0 : 1, true); });
range.addEventListener('input', () => {
  autoFolded = true;
  cancelAnimationFrame(syncing); syncing = 0;
  fold(Number(range.value) / 100, false);
});

/* ── orbit ── */
function writeCam() {
  root.style.setProperty('--fxd-dieline-yaw', yaw.toFixed(2) + 'deg');
  root.style.setProperty('--fxd-dieline-tilt', tilt.toFixed(2) + 'deg');
}
const clampTilt = (t) => Math.max(14, Math.min(82, t));

stage.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  cancelAnimationFrame(spin); spin = 0;
  drag = { id: e.pointerId, x: e.clientX, y: e.clientY, t: performance.now() };
  stage.setPointerCapture(e.pointerId);
  root.setAttribute('data-drag', '');
  vyaw = vtilt = 0;
});
stage.addEventListener('pointermove', (e) => {
  if (!drag || e.pointerId !== drag.id) return;
  const now = performance.now(), dt = Math.max(8, now - drag.t);
  const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
  yaw += dx * 0.42;
  tilt = clampTilt(tilt - dy * 0.32);
  vyaw = (dx * 0.42) / dt * 16; vtilt = (-dy * 0.32) / dt * 16;
  drag.x = e.clientX; drag.y = e.clientY; drag.t = now;
  writeCam();
});
function endDrag(e) {
  if (!drag || e.pointerId !== drag.id) return;
  drag = null;
  if (calm.matches || Math.hypot(vyaw, vtilt) < 0.2) { root.removeAttribute('data-drag'); return; }
  let last = 0;
  const coast = (now) => {
    if (!root.isConnected) return;
    const dt = last ? Math.min(40, now - last) / 16.67 : 1;
    last = now;
    const k = Math.pow(0.93, dt);
    vyaw *= k; vtilt *= k;
    yaw += vyaw * dt; tilt = clampTilt(tilt + vtilt * dt);
    writeCam();
    if (Math.hypot(vyaw, vtilt) > 0.03) spin = requestAnimationFrame(coast);
    else { spin = 0; root.removeAttribute('data-drag'); }
  };
  spin = requestAnimationFrame(coast);
}
stage.addEventListener('pointerup', endDrag);
stage.addEventListener('pointercancel', endDrag);

stage.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft') yaw -= 15;
  else if (e.key === 'ArrowRight') yaw += 15;
  else if (e.key === 'ArrowUp') tilt = clampTilt(tilt - 8);
  else if (e.key === 'ArrowDown') tilt = clampTilt(tilt + 8);
  else if (e.key === 'Enter' || e.key === ' ') { autoFolded = true; fold(target >= 0.5 ? 0 : 1, true); e.preventDefault(); return; }
  else if (e.key === 'Home') { yaw = -28; tilt = 54; }
  else return;
  e.preventDefault();
  writeCam();
});

paint(0);
setButton();

/* fold itself once, the first time it scrolls into view */
let autoTimer = 0;
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); clearTimeout(autoTimer); return; }
  seen = entries[0].isIntersecting;
  root.toggleAttribute('data-off', !seen);
  if (seen && !autoFolded && !calm.matches) {
    autoTimer = setTimeout(() => {
      if (!root.isConnected || autoFolded) return;
      autoFolded = true;
      fold(1, true);
    }, 1100);
  } else clearTimeout(autoTimer);
});
io.observe(root);

css:
.fxd-terrain {
  /* Re-theme with these four; the canvas reads them. */
  --fxd-terrain-sky: oklch(0.24 0.045 28);
  --fxd-terrain-glow: oklch(0.72 0.13 58);
  --fxd-terrain-line: oklch(0.95 0.035 82);
  --fxd-terrain-ground: oklch(0.17 0.03 30);

  --fxd-terrain-muted: color-mix(in oklch, var(--fxd-terrain-line) 62%, var(--fxd-terrain-sky));
  --fxd-terrain-chip: color-mix(in oklch, var(--fxd-terrain-ground) 62%, transparent);
  --fxd-terrain-edge: color-mix(in oklch, var(--fxd-terrain-line) 16%, transparent);

  container-type: inline-size;
  position: relative;
  isolation: isolate;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 4 / 3;
  min-block-size: 220px;
  max-block-size: 380px;
  border-radius: 18px;
  overflow: hidden;
  background: var(--fxd-terrain-ground);
  color: var(--fxd-terrain-line);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxd-terrain-edge);

  & .fxd-terrain__view {
    position: absolute;
    inset: 0;
    cursor: crosshair;
    touch-action: none;
    outline: none;
  }
  & .fxd-terrain__view:focus-visible { box-shadow: inset 0 0 0 2px var(--fxd-terrain-glow); }
  & .fxd-terrain__cv {
    position: absolute;
    inset: 0;
    display: block;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxd-terrain__probe { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }

  /* flight-path marker: rides with the bank angle */
  & .fxd-terrain__fpm {
    position: absolute;
    left: 50%;
    top: 47%;
    inline-size: clamp(30px, 11cqi, 44px);
    translate: -50% -50%;
    rotate: var(--fxd-terrain-bank, 0deg);
    fill: none;
    stroke: var(--fxd-terrain-line);
    stroke-width: 1.5;
    stroke-linecap: round;
    opacity: .8;
    filter: drop-shadow(0 0 3px color-mix(in oklch, var(--fxd-terrain-ground) 80%, transparent));
    pointer-events: none;
  }

  & .fxd-terrain__head {
    position: absolute;
    inset: 0 auto auto 0;
    padding: clamp(12px, 4cqi, 18px);
    pointer-events: none;
    text-shadow: 0 1px 8px color-mix(in oklch, var(--fxd-terrain-sky) 80%, transparent);
  }
  & .fxd-terrain__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxd-terrain-muted);
  }
  & .fxd-terrain__title {
    margin: 3px 0 0;
    font-size: clamp(17px, 6.2cqi, 26px);
    font-weight: 300;
    letter-spacing: -.01em;
    line-height: 1.05;
    text-wrap: balance;
  }

  & .fxd-terrain__hud {
    position: absolute;
    left: clamp(10px, 3.4cqi, 16px);
    bottom: clamp(10px, 3.4cqi, 16px);
    display: flex;
    gap: 2px;
    margin: 0;
    padding: 4px;
    border-radius: 10px;
    background: var(--fxd-terrain-chip);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px var(--fxd-terrain-edge);
    pointer-events: none;
  }
  & .fxd-terrain__hud div {
    display: grid;
    gap: 2px;
    min-inline-size: 7ch;
    padding: 4px 8px;
  }
  & .fxd-terrain__hud div + div { box-shadow: -1px 0 0 var(--fxd-terrain-edge); }
  & .fxd-terrain__hud dt {
    font: 600 9px/1 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxd-terrain-muted);
  }
  & .fxd-terrain__hud dd {
    display: flex;
    align-items: baseline;
    gap: 2px;
    margin: 0;
    font: 500 clamp(12px, 3.7cqi, 15px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxd-terrain__hud dd span { font-size: .72em; color: var(--fxd-terrain-muted); }

  & .fxd-terrain__pause {
    position: absolute;
    right: clamp(10px, 3.4cqi, 16px);
    bottom: clamp(10px, 3.4cqi, 16px);
    display: grid;
    place-items: center;
    inline-size: 38px;
    block-size: 38px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: var(--fxd-terrain-chip);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px var(--fxd-terrain-edge);
    color: var(--fxd-terrain-line);
    cursor: pointer;
    transition: background-color .2s, scale .3s cubic-bezier(.34, 1.56, .64, 1);
  }
  & .fxd-terrain__pause:hover { background: color-mix(in oklch, var(--fxd-terrain-glow) 35%, var(--fxd-terrain-chip)); }
  & .fxd-terrain__pause:active { scale: .92; }
  & .fxd-terrain__pause:focus-visible { outline: 2px solid var(--fxd-terrain-glow); outline-offset: 2px; }
  & .fxd-terrain__pause svg {
    inline-size: 16px;
    block-size: 16px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxd-terrain__ic-play { display: none; fill: currentColor; }
  & .fxd-terrain__pause[aria-pressed="true"] .fxd-terrain__ic-play { display: inline; }
  & .fxd-terrain__pause[aria-pressed="true"] .fxd-terrain__ic-pause { display: none; }

  @container (max-width: 300px) {
    & .fxd-terrain__hud div { min-inline-size: 6ch; padding: 3px 6px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxd-terrain .fxd-terrain__pause { transition: none; }
}

js:
/* Ridgeline flyover — hidden-line removal by painter's algorithm.
   The ground is sampled on rows perpendicular to the flight path. Rows are
   anchored to the distance flown (not to the screen), so ridges flow toward
   the viewer instead of boiling in place. Each row is projected through a
   pinhole camera, then drawn far to near: its fill runs down past the bottom
   of the frame and covers every line behind it, and only then is its own
   line stroked. Units are kilometres. */
const view = root.querySelector('.fxd-terrain__view');
const cv = root.querySelector('.fxd-terrain__cv');
const ctx = cv.getContext('2d');
const probe = root.querySelector('.fxd-terrain__probe');
const pauseBtn = root.querySelector('.fxd-terrain__pause');
const out = { alt: root.querySelector('[data-k="alt"]'), hdg: root.querySelector('[data-k="hdg"]'), dist: root.querySelector('[data-k="dist"]') };
const calm = matchMedia('(prefers-reduced-motion: reduce)');
if (!ctx) return;

/* ── colour tokens → rgb, via a 1×1 canvas so oklch() works everywhere ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const pal = {};
function theme() {
  pal.sky = rgb('--fxd-terrain-sky');
  pal.glow = rgb('--fxd-terrain-glow');
  pal.line = rgb('--fxd-terrain-line');
  pal.ground = rgb('--fxd-terrain-ground');
  pal.sun = mix(pal.glow, [255, 250, 235], .55);
}
const mix = (a, b, k) => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
const css = (c, a = 1) => 'rgba(' + (c[0] | 0) + ',' + (c[1] | 0) + ',' + (c[2] | 0) + ',' + a + ')';

/* ── seeded gradient noise ── */
const perm = new Uint8Array(512);
{
  const p = Array.from({ length: 256 }, (_, i) => i);
  let s = 707;
  for (let i = 255; i > 0; i--) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    const j = s % (i + 1);
    [p[i], p[j]] = [p[j], p[i]];
  }
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
}
const GX = [1, -1, 1, -1, 1.414, -1.414, 0, 0], GY = [1, 1, -1, -1, 0, 0, 1.414, -1.414];
function noise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const X = xi & 255, Y = yi & 255;
  const u = xf * xf * xf * (xf * (xf * 6 - 15) + 10), v = yf * yf * yf * (yf * (yf * 6 - 15) + 10);
  const a = perm[X + perm[Y]] & 7, b = perm[X + 1 + perm[Y]] & 7;
  const c = perm[X + perm[Y + 1]] & 7, d = perm[X + 1 + perm[Y + 1]] & 7;
  const n00 = GX[a] * xf + GY[a] * yf, n10 = GX[b] * (xf - 1) + GY[b] * yf;
  const n01 = GX[c] * xf + GY[c] * (yf - 1), n11 = GX[d] * (xf - 1) + GY[d] * (yf - 1);
  const nx0 = n00 + (n10 - n00) * u, nx1 = n01 + (n11 - n01) * u;
  return nx0 + (nx1 - nx0) * v;
}
/* ridged multifractal over a broad swell: sharp crests, soft valleys */
function height(x, y) {
  let sum = 0, amp = 0.55, f = 0.42, w = 1;
  for (let o = 0; o < 4; o++) {
    let r = 1 - Math.abs(noise(x * f + o * 17.1, y * f - o * 9.3));
    r *= r * w;
    w = Math.min(1, r * 1.6);
    sum += r * amp;
    amp *= 0.48; f *= 2.07;
  }
  const swell = noise(x * 0.09 + 40, y * 0.09 - 12) * 0.5 + 0.5;
  return sum * (0.35 + 0.9 * swell) * 1.15;          /* km above the valley floor */
}

/* ── flight state ── */
const FLOOR = 0.62;                        /* valley floor above sea level, km */
const SPEED = 0.26;                        /* km/s ≈ 940 km/h */
const SUN_AZ = 262 * Math.PI / 180;        /* the sun sits in the west-south-west */
const ROWS = 64, DZ = 0.17;
let W = 0, H = 0, DPR = 1, cols = 80;
let cx = 0, cy = 0, hdg = 274 * Math.PI / 180, alt = 1.2, travel = 0;
let turn = 0, bank = 0, altTarget = 1.2;
let pointer = null, keyTurn = 0, keyClimb = 0, lastInput = -1e9;
let paused = calm.matches, seen = false, raf = 0, last = 0;
let rows = [];

function resize() {
  const r = cv.getBoundingClientRect();
  if (!r.width || !r.height) return;
  W = r.width; H = r.height;
  DPR = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  cols = Math.max(48, Math.min(120, Math.round(W / 4.5)));
  rows = Array.from({ length: ROWS }, () => new Float32Array((cols + 1) * 2));
  draw();
}

function groundAhead() {
  const fx = Math.sin(hdg), fy = Math.cos(hdg);
  let m = 0;
  for (let k = 0; k < 4; k++) m = Math.max(m, height(cx + fx * k * 0.35, cy + fy * k * 0.35));
  return m;
}

function step(dt, now) {
  const t = now / 1000;
  /* autopilot weaves gently when nobody is steering */
  const idle = now - lastInput > 2500 && !pointer;
  let want = keyTurn * 0.55;
  if (pointer) want += (pointer.x - 0.5) * 1.1;
  else if (idle) want += Math.sin(t * 0.21) * 0.16 + Math.sin(t * 0.077) * 0.1;
  turn += (want - turn) * (1 - Math.exp(-dt * 2.6));
  hdg += turn * dt;
  bank += (turn * 0.36 - bank) * (1 - Math.exp(-dt * 3));
  if (pointer) altTarget = 0.75 + (1 - pointer.y) * 1.25;
  else if (idle) altTarget = 1.15 + Math.sin(t * 0.13) * 0.18;
  altTarget = Math.max(0.55, Math.min(2.4, altTarget + keyClimb * dt * 0.6));
  const clear = groundAhead() + 0.22;
  const goal = Math.max(altTarget, clear);
  alt += (goal - alt) * (1 - Math.exp(-dt * (goal > alt ? 2.4 : 0.9)));
  const d = SPEED * dt;
  cx += Math.sin(hdg) * d; cy += Math.cos(hdg) * d;
  travel += d;
}

function draw() {
  if (!W || !pal.sky) return;
  const g = ctx;
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  const f = W * 0.82, horizon = H * 0.4, far = ROWS * DZ;
  /* bank the whole world about the frame centre */
  g.translate(W / 2, H * 0.47);
  g.rotate(-bank);
  g.translate(-W / 2, -H * 0.47);
  const ext = Math.hypot(W, H);
  const L = W / 2 - ext, R = W / 2 + ext, B = H / 2 + ext;

  /* sky */
  const sky = g.createLinearGradient(0, horizon - H * 0.75, 0, horizon + 4);
  sky.addColorStop(0, css(pal.sky));
  sky.addColorStop(0.62, css(mix(pal.sky, pal.glow, .45)));
  sky.addColorStop(1, css(pal.glow));
  g.fillStyle = sky;
  g.fillRect(L, horizon - ext, R - L, ext + H);

  /* the sun, placed by its bearing relative to our heading */
  let rel = SUN_AZ - hdg;
  rel = Math.atan2(Math.sin(rel), Math.cos(rel));
  if (Math.abs(rel) < 1.2) {
    const sx = W / 2 + Math.tan(rel) * f, sy = horizon - H * 0.035;
    const halo = g.createRadialGradient(sx, sy, 0, sx, sy, H * 0.55);
    halo.addColorStop(0, css(pal.sun, .55));
    halo.addColorStop(0.25, css(pal.glow, .25));
    halo.addColorStop(1, css(pal.glow, 0));
    g.fillStyle = halo;
    g.fillRect(sx - H * 0.6, sy - H * 0.6, H * 1.2, H * 1.2);
    g.fillStyle = css(pal.sun);
    g.beginPath(); g.arc(sx, sy, Math.max(7, H * 0.045), 0, Math.PI * 2); g.fill();
  }

  /* rows, anchored to the distance flown */
  const fx = Math.sin(hdg), fy = Math.cos(hdg), rx = Math.cos(hdg), ry = -Math.sin(hdg);
  const base = Math.floor(travel / DZ);
  const eye = alt + FLOOR;
  for (let k = ROWS; k >= 1; k--) {
    const z = (base + k) * DZ - travel;
    if (z < 0.18) continue;
    const half = (ext / f) * z * 1.05;
    const pts = rows[k - 1];
    for (let i = 0; i <= cols; i++) {
      const x = -half + (2 * half * i) / cols;
      const wx = cx + rx * x + fx * z, wy = cy + ry * x + fy * z;
      const h = height(wx, wy) + FLOOR;
      pts[i * 2] = W / 2 + (x * f) / z;
      pts[i * 2 + 1] = horizon + ((eye - h) * f) / z;
    }
    const fog = Math.pow(z / far, 1.15);
    const fade = 1 - Math.max(0, (z - far * 0.82) / (far * 0.18));
    g.beginPath();
    g.moveTo(pts[0], pts[1]);
    for (let i = 1; i <= cols; i++) g.lineTo(pts[i * 2], pts[i * 2 + 1]);
    g.lineTo(pts[cols * 2], B); g.lineTo(pts[0], B); g.closePath();
    g.fillStyle = css(mix(pal.ground, pal.glow, Math.min(1, fog * 0.85)));
    g.fill();
    g.beginPath();
    g.moveTo(pts[0], pts[1]);
    for (let i = 1; i <= cols; i++) g.lineTo(pts[i * 2], pts[i * 2 + 1]);
    g.strokeStyle = css(mix(pal.line, pal.glow, Math.min(1, fog * 1.1)), (0.25 + 0.75 * (1 - fog)) * fade);
    g.lineWidth = z < 1.2 ? 1.6 : z < 4 ? 1.15 : 0.85;
    g.stroke();
  }
  g.setTransform(1, 0, 0, 1, 0, 0);
  root.style.setProperty('--fxd-terrain-bank', (-bank * 180 / Math.PI).toFixed(2) + 'deg');
}

let hudAt = 0;
function hud(now, force) {
  if (!force && now - hudAt < 120) return;
  hudAt = now;
  const deg = ((hdg * 180 / Math.PI) % 360 + 360) % 360;
  out.alt.textContent = Math.round((alt + FLOOR) * 1000).toLocaleString('en-US');
  out.hdg.textContent = String(Math.round(deg) % 360).padStart(3, '0');
  out.dist.textContent = travel.toFixed(1);
}

function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = Math.min(0.05, (now - (last || now)) / 1000);
  last = now;
  if (!paused) step(dt, now);
  draw();
  hud(now);
  if (seen && !paused) raf = requestAnimationFrame(frame);
}
function kick() {
  if (!raf && seen) { last = 0; raf = requestAnimationFrame(frame); }
}

/* a still render after a manual nudge while paused */
function nudge(dh, da) {
  hdg += dh; altTarget = Math.max(0.55, Math.min(2.4, altTarget + da));
  alt = Math.max(altTarget, groundAhead() + 0.22);
  lastInput = performance.now();
  if (paused) { draw(); hud(0, true); } else kick();
}

function setPaused(p) {
  paused = p;
  pauseBtn.setAttribute('aria-pressed', p ? 'true' : 'false');
  pauseBtn.setAttribute('aria-label', p ? 'Resume flight' : 'Pause flight');
  if (!p) kick();
}
pauseBtn.addEventListener('click', () => setPaused(!paused));

view.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'touch' && !e.buttons) return;
  const r = view.getBoundingClientRect();
  pointer = { x: (e.clientX - r.left) / r.width, y: (e.clientY - r.top) / r.height };
  lastInput = performance.now();
});
view.addEventListener('pointerdown', (e) => {
  if (e.pointerType === 'touch') view.setPointerCapture(e.pointerId);
});
view.addEventListener('pointerleave', () => { pointer = null; lastInput = performance.now(); });
view.addEventListener('pointerup', (e) => { if (e.pointerType === 'touch') pointer = null; });

view.addEventListener('keydown', (e) => {
  const k = e.key;
  if (k === ' ') { setPaused(!paused); e.preventDefault(); return; }
  if (paused) {
    if (k === 'ArrowLeft') nudge(-0.12, 0);
    else if (k === 'ArrowRight') nudge(0.12, 0);
    else if (k === 'ArrowUp') nudge(0, 0.15);
    else if (k === 'ArrowDown') nudge(0, -0.15);
    else return;
    e.preventDefault();
    return;
  }
  if (k === 'ArrowLeft') keyTurn = -1;
  else if (k === 'ArrowRight') keyTurn = 1;
  else if (k === 'ArrowUp') keyClimb = 1;
  else if (k === 'ArrowDown') keyClimb = -1;
  else return;
  lastInput = performance.now();
  e.preventDefault();
});
view.addEventListener('keyup', (e) => {
  if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') keyTurn = 0;
  if (e.key === 'ArrowUp' || e.key === 'ArrowDown') keyClimb = 0;
});
view.addEventListener('blur', () => { keyTurn = 0; keyClimb = 0; });

theme();
alt = Math.max(altTarget, groundAhead() + 0.22);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  resize();
});
ro.observe(cv);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  seen = entries[0].isIntersecting;
  if (seen) { draw(); kick(); }
});
io.observe(root);
setPaused(paused);
hud(0, true);

css:
.fxd-scatter {
  /* Re-theme: paper and ink, plus one colour per region. */
  --fxd-scatter-paper: oklch(0.985 0.006 95);
  --fxd-scatter-ink: oklch(0.27 0.022 255);
  --fxd-scatter-s1: oklch(0.63 0.155 38);
  --fxd-scatter-s2: oklch(0.75 0.135 82);
  --fxd-scatter-s3: oklch(0.6 0.115 152);
  --fxd-scatter-s4: oklch(0.52 0.13 335);

  --fxd-scatter-muted: color-mix(in oklch, var(--fxd-scatter-ink) 58%, var(--fxd-scatter-paper));
  --fxd-scatter-line: color-mix(in oklch, var(--fxd-scatter-ink) 12%, transparent);
  --fxd-scatter-wash: color-mix(in oklch, var(--fxd-scatter-ink) 5%, var(--fxd-scatter-paper));
  --fxd-scatter-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 8px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 6;
  min-block-size: 330px;
  max-block-size: 400px;
  padding: 14px 14px 12px;
  border-radius: 18px;
  background: var(--fxd-scatter-paper);
  color: var(--fxd-scatter-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxd-scatter-line);

  & .fxd-scatter__head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 10px;
  }
  & .fxd-scatter__eyebrow {
    margin: 0;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: .09em;
    text-transform: uppercase;
    color: var(--fxd-scatter-muted);
  }
  & .fxd-scatter__title {
    margin: 2px 0 0;
    font-size: clamp(17px, 6cqi, 22px);
    font-weight: 720;
    letter-spacing: -.02em;
    line-height: 1.1;
    text-wrap: balance;
  }
  & .fxd-scatter__total {
    margin: 0 0 2px;
    font-size: 12px;
    white-space: nowrap;
    color: var(--fxd-scatter-muted);
  }
  & .fxd-scatter__total b {
    font: 650 13px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxd-scatter-ink);
  }

  /* ── plot ── */
  & .fxd-scatter__plot {
    position: relative;
    min-block-size: 0;
    border-radius: 12px;
    background: radial-gradient(90% 80% at 50% 55%, var(--fxd-scatter-paper), var(--fxd-scatter-wash));
    cursor: grab;
    touch-action: none;
    outline: none;
  }
  &[data-drag] .fxd-scatter__plot { cursor: grabbing; }
  &[data-hover] .fxd-scatter__plot { cursor: pointer; }
  & .fxd-scatter__plot:focus-visible { box-shadow: 0 0 0 2px var(--fxd-scatter-ink); }
  & .fxd-scatter__cv {
    position: absolute;
    inset: 0;
    display: block;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxd-scatter__probe { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }
  & .fxd-scatter__plane {
    position: absolute;
    left: 10px;
    top: 8px;
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .06em;
    text-transform: uppercase;
    color: var(--fxd-scatter-muted);
    pointer-events: none;
  }

  & .fxd-scatter__tip {
    position: absolute;
    left: 0;
    top: 0;
    z-index: 2;
    min-inline-size: 150px;
    padding: 9px 10px 8px;
    border-radius: 10px;
    background: color-mix(in oklch, var(--fxd-scatter-paper) 94%, transparent);
    backdrop-filter: blur(6px);
    box-shadow:
      0 0 0 1px var(--fxd-scatter-line),
      0 10px 24px -10px color-mix(in oklch, var(--fxd-scatter-ink) 40%, transparent);
    pointer-events: none;
    opacity: 0;
    scale: .96;
    transform-origin: var(--ox, 0) var(--oy, 100%);
    transition: opacity .16s, scale .3s var(--fxd-scatter-out);
  }
  &[data-tip] .fxd-scatter__tip { opacity: 1; scale: 1; }
  & .fxd-scatter__tname {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 0;
    font-size: 13px;
    font-weight: 680;
    white-space: nowrap;
  }
  & .fxd-scatter__tname i {
    inline-size: 8px;
    block-size: 8px;
    border-radius: 50%;
    background: var(--tc, var(--fxd-scatter-ink));
  }
  & .fxd-scatter__tregion {
    margin: 1px 0 6px 14px;
    font-size: 11px;
    color: var(--fxd-scatter-muted);
  }
  & .fxd-scatter__tvals {
    display: grid;
    grid-template-columns: repeat(4, auto);
    gap: 8px;
    margin: 0;
    padding-block-start: 6px;
    border-block-start: 1px solid var(--fxd-scatter-line);
  }
  & .fxd-scatter__tvals div { display: grid; gap: 1px; }
  & .fxd-scatter__tvals dt {
    font-size: 9px;
    font-weight: 650;
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--fxd-scatter-muted);
  }
  & .fxd-scatter__tvals dd {
    margin: 0;
    font: 600 12px/1.1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }

  /* ── controls ── */
  & .fxd-scatter__bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 10px;
  }
  & .fxd-scatter__views {
    display: inline-flex;
    padding: 2px;
    border-radius: 9px;
    background: var(--fxd-scatter-wash);
    box-shadow: inset 0 0 0 1px var(--fxd-scatter-line);
  }
  & .fxd-scatter__views button {
    padding: 5px 9px;
    border: 0;
    border-radius: 7px;
    background: transparent;
    color: var(--fxd-scatter-muted);
    font: 600 11.5px/1.1 system-ui, sans-serif;
    cursor: pointer;
    transition: background-color .2s, color .2s, box-shadow .2s;
  }
  & .fxd-scatter__views button:hover { color: var(--fxd-scatter-ink); }
  & .fxd-scatter__views button[aria-pressed="true"] {
    background: var(--fxd-scatter-paper);
    color: var(--fxd-scatter-ink);
    box-shadow: 0 1px 2px color-mix(in oklch, var(--fxd-scatter-ink) 18%, transparent), 0 0 0 1px var(--fxd-scatter-line);
  }
  & .fxd-scatter__views button:focus-visible,
  & .fxd-scatter__legend button:focus-visible { outline: 2px solid var(--fxd-scatter-ink); outline-offset: 1px; }

  & .fxd-scatter__legend {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  & .fxd-scatter__legend button {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 4px 8px 4px 6px;
    border: 0;
    border-radius: 999px;
    background: color-mix(in oklch, var(--c) 12%, var(--fxd-scatter-paper));
    color: var(--fxd-scatter-ink);
    font: 560 11px/1.1 system-ui, sans-serif;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color .2s, color .2s, opacity .2s;
  }
  & .fxd-scatter__legend button:hover { background: color-mix(in oklch, var(--c) 22%, var(--fxd-scatter-paper)); }
  & .fxd-scatter__legend i {
    inline-size: 8px;
    block-size: 8px;
    border-radius: 50%;
    background: var(--c);
    box-shadow: 0 0 0 1.5px var(--fxd-scatter-paper);
    transition: scale .35s cubic-bezier(.34, 1.56, .64, 1);
  }
  & .fxd-scatter__legend b {
    font: 600 10.5px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxd-scatter-muted);
  }
  & .fxd-scatter__legend button[aria-pressed="false"] {
    background: transparent;
    color: var(--fxd-scatter-muted);
    box-shadow: inset 0 0 0 1px var(--fxd-scatter-line);
  }
  & .fxd-scatter__legend button[aria-pressed="false"] i { scale: .5; background: var(--fxd-scatter-muted); }
  & .fxd-scatter__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @container (min-width: 520px) {
    & .fxd-scatter__bar { justify-content: space-between; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxd-scatter .fxd-scatter__tip,
  .fxd-scatter .fxd-scatter__legend i,
  .fxd-scatter .fxd-scatter__legend button,
  .fxd-scatter .fxd-scatter__views button { transition: none; }
}

js:
/* Flavour space — a 3D scatter on a 2D canvas.
   World axes: x = acidity, y = sweetness (up), z = body (high body at the
   back), each 0–10 mapped to −1…1. The camera is a yaw about y then a pitch
   about x, with a little perspective in the free view that eases to zero in
   the axis views, so Top / Front / Side are true 2D projections of the same
   points. Walls are drawn on whichever side of the cube faces away from the
   camera, so the grid always sits behind the data. */
const plot = root.querySelector('.fxd-scatter__plot');
const cv = root.querySelector('.fxd-scatter__cv');
const ctx = cv.getContext('2d');
const probe = root.querySelector('.fxd-scatter__probe');
const tip = root.querySelector('.fxd-scatter__tip');
const planeEl = root.querySelector('.fxd-scatter__plane');
const shownEl = root.querySelector('[data-k="shown"]');
const sr = root.querySelector('.fxd-scatter__sr');
const viewBtns = [...root.querySelectorAll('[data-view]')];
const legendBtns = [...root.querySelectorAll('[data-r]')];
const calm = matchMedia('(prefers-reduced-motion: reduce)');
if (!ctx) return;

const REGIONS = ['East Africa', 'Central America', 'Andes', 'Pacific Islands'];
/* name, region, acidity, body, sweetness, cup score */
const LOTS = [
  ['Halo Bera', 0, 8.8, 5.5, 5.5, 86.5], ['Gidi Sora', 0, 8.0, 5.1, 8.2, 87.5], ['Kanyon AA', 0, 8.3, 3.9, 6.9, 87.5],
  ['Mara Terrace', 0, 6.7, 4.4, 6.8, 87.0], ['Wote Hill', 0, 9.3, 5.8, 5.7, 87.25], ['Seru Natural', 0, 8.6, 4.7, 6.6, 86.75],
  ['Ombe Station', 0, 9.6, 4.7, 8.2, 87.75], ['Lalo Ridge', 0, 4.9, 5.5, 7.4, 87.0], ['Chebe Wash', 0, 7.9, 5.8, 8.0, 87.5],
  ['Las Nubes', 1, 5.5, 7.3, 7.8, 87.0], ['Cerro Azulado', 1, 5.6, 6.5, 6.8, 86.5], ['El Mirlo', 1, 5.9, 4.8, 7.5, 87.0],
  ['Loma Clara', 1, 4.5, 6.2, 7.6, 87.5], ['San Ubaldo', 1, 7.3, 5.1, 7.7, 86.75], ['La Quebradita', 1, 6.5, 6.5, 8.8, 88.0],
  ['Finca Rocío', 1, 6.8, 7.0, 8.3, 87.5], ['Volcán Tierno', 1, 5.8, 6.2, 8.4, 87.25],
  ['Alto Cañaveral', 2, 4.6, 5.2, 7.0, 87.25], ['Huaca Verde', 2, 4.4, 6.7, 6.3, 87.0], ['Pampa Rosa', 2, 4.8, 6.1, 6.6, 87.0],
  ['Cerro Inti', 2, 4.8, 7.3, 6.6, 87.0], ['Valle Hondo', 2, 5.6, 6.3, 6.1, 86.75], ['La Esmeraldita', 2, 3.5, 7.1, 6.5, 86.5],
  ['Quebrada Fría', 2, 6.4, 7.7, 5.3, 86.75], ['Santa Lucía Alta', 2, 6.7, 6.2, 5.9, 86.25],
  ['Bukit Senja', 3, 5.1, 7.9, 4.1, 86.25], ['Lembah Kabut', 3, 1.3, 9.0, 6.9, 86.5], ['Tana Rame', 3, 3.1, 9.0, 5.6, 86.5],
  ['Ulu Sari', 3, 4.6, 9.2, 4.7, 85.75], ['Waru Laut', 3, 3.9, 9.5, 5.4, 87.0], ['Pulo Mandi', 3, 4.7, 9.1, 5.4, 87.0],
  ['Sembra Wet-Hulled', 3, 4.6, 9.5, 5.1, 86.75],
];
const P = LOTS.map(([name, r, a, b, s, score]) => ({
  name, r, a, b, s, score,
  x: (a - 5) / 5, y: (s - 5) / 5, z: (5 - b) / 5,
  vis: 1, sx: 0, sy: 0, sz: 0, k: 1,
}));
const hidden = new Set();

const VIEWS = {
  orbit: { yaw: -0.62, pitch: 0.42, persp: 0.14, zoom: 1, label: 'Drag to orbit' },
  top: { yaw: 0, pitch: Math.PI / 2, persp: 0, zoom: 1.3, label: 'Top · acidity × body' },
  front: { yaw: 0, pitch: 0, persp: 0, zoom: 1.3, label: 'Front · acidity × sweetness' },
  side: { yaw: -Math.PI / 2, pitch: 0, persp: 0, zoom: 1.3, label: 'Side · body × sweetness' },
};
const cam = { yaw: VIEWS.orbit.yaw, pitch: VIEWS.orbit.pitch, persp: VIEWS.orbit.persp, zoom: 1 };
let view = 'orbit', tween = null, vy = 0, vp = 0;
let W = 0, H = 0, DPR = 1, S = 1, CX = 0, CY = 0;
let hover = -1, pick = -1, drag = null, lastInput = -1e9, seen = false, raf = 0, last = 0;

/* ── palette ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const pal = {};
function theme() {
  pal.paper = rgb('--fxd-scatter-paper');
  pal.ink = rgb('--fxd-scatter-ink');
  pal.s = [1, 2, 3, 4].map((i) => rgb('--fxd-scatter-s' + i));
}
const css = (c, a = 1) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';

/* ── projection ── */
let cyw = 1, syw = 0, cp = 1, sp = 0;
function setRot() { cyw = Math.cos(cam.yaw); syw = Math.sin(cam.yaw); cp = Math.cos(cam.pitch); sp = Math.sin(cam.pitch); }
const out3 = [0, 0, 0, 1];
function project(x, y, z) {
  const x1 = x * cyw + z * syw, z1 = -x * syw + z * cyw;
  const y2 = y * cp - z1 * sp, z2 = y * sp + z1 * cp;
  const k = cam.zoom / (1 - z2 * cam.persp);
  out3[0] = CX + x1 * S * k; out3[1] = CY - y2 * S * k; out3[2] = z2; out3[3] = k;
  return out3;
}
/* depth of a direction (no translation) — which way a face points */
const facing = (nx, ny, nz) => { const z1 = -nx * syw + nz * cyw; return ny * sp + z1 * cp; };

function resize() {
  const r = cv.getBoundingClientRect();
  if (!r.width || !r.height) return;
  W = r.width; H = r.height;
  DPR = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  S = Math.min(W * 0.27, H * 0.255);
  CX = W / 2; CY = H * 0.47;
  draw();
}

function line(a, b) {
  const p = project(a[0], a[1], a[2]); const ax = p[0], ay = p[1];
  const q = project(b[0], b[1], b[2]);
  ctx.moveTo(ax, ay); ctx.lineTo(q[0], q[1]);
}

function draw() {
  if (!W || !pal.paper) return;
  setRot();
  const g = ctx;
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  g.clearRect(0, 0, W, H);

  const wx = facing(1, 0, 0) < 0 ? 1 : -1;     /* back x-wall */
  const wz = facing(0, 0, 1) < 0 ? 1 : -1;     /* back z-wall */
  const floorShows = facing(0, -1, 0) < 0;
  const T = [-1, -0.6, -0.2, 0.2, 0.6, 1];     /* every 2 points on the 0–10 scale */

  /* walls: a faint wash, a grid, a firmer outline */
  const walls = [];
  if (floorShows) walls.push((u, v) => [u, -1, v]);
  if (Math.abs(facing(1, 0, 0)) > 0.02) walls.push((u, v) => [wx, v, u]);
  if (Math.abs(facing(0, 0, 1)) > 0.02) walls.push((u, v) => [u, v, wz]);
  for (const f of walls) {
    g.beginPath();
    let p = project(...f(-1, -1)); g.moveTo(p[0], p[1]);
    p = project(...f(1, -1)); g.lineTo(p[0], p[1]);
    p = project(...f(1, 1)); g.lineTo(p[0], p[1]);
    p = project(...f(-1, 1)); g.lineTo(p[0], p[1]);
    g.closePath();
    g.fillStyle = css(pal.ink, 0.025); g.fill();
    g.strokeStyle = css(pal.ink, 0.22); g.lineWidth = 1; g.stroke();
    g.beginPath();
    for (const t of T.slice(1, -1)) { line(f(t, -1), f(t, 1)); line(f(-1, t), f(1, t)); }
    g.strokeStyle = css(pal.ink, 0.07); g.stroke();
  }

  /* points, far to near */
  for (const p of P) {
    const q = project(p.x, p.y, p.z);
    p.sx = q[0]; p.sy = q[1]; p.sz = q[2]; p.k = q[3];
  }
  const order = P.map((_, i) => i).sort((a, b) => P[a].sz - P[b].sz);

  /* drop line and floor shadow for the hovered or picked lot */
  const focus = hover >= 0 ? hover : pick;
  if (focus >= 0 && P[focus].vis > 0.5) {
    const p = P[focus];
    const f0 = project(p.x, -1, p.z); const fx = f0[0], fy = f0[1];
    g.setLineDash([3, 3]);
    g.beginPath(); g.moveTo(p.sx, p.sy); g.lineTo(fx, fy);
    g.strokeStyle = css(pal.ink, 0.45); g.lineWidth = 1; g.stroke();
    g.setLineDash([]);
    g.beginPath(); g.ellipse(fx, fy, 5, 5 * Math.max(0.25, Math.abs(sp)), 0, 0, Math.PI * 2);
    g.fillStyle = css(pal.ink, 0.18); g.fill();
    /* the same lot's reading on each back wall */
    g.beginPath();
    let a = project(wx, p.y, p.z); g.moveTo(p.sx, p.sy); g.lineTo(a[0], a[1]);
    a = project(p.x, p.y, wz); g.moveTo(p.sx, p.sy); g.lineTo(a[0], a[1]);
    g.strokeStyle = css(pal.ink, 0.12); g.stroke();
  }

  const zmin = -1.75, zmax = 1.75;
  for (const i of order) {
    const p = P[i];
    if (p.vis < 0.01) continue;
    const depth = (p.sz - zmin) / (zmax - zmin);            /* 0 far … 1 near */
    const r = (3 + (p.score - 85.5) * 1.6) * (p.k / cam.zoom) * (0.35 + 0.65 * p.vis) * Math.max(0.9, Math.min(1.3, S / 72));
    const col = pal.s[p.r];
    g.globalAlpha = p.vis * (0.55 + 0.45 * depth);
    g.beginPath(); g.arc(p.sx, p.sy, r, 0, Math.PI * 2);
    g.fillStyle = css(col); g.fill();
    g.lineWidth = 1.4; g.strokeStyle = css(pal.paper); g.stroke();
    if (i === focus) {
      g.globalAlpha = 1;
      g.beginPath(); g.arc(p.sx, p.sy, r + 3.5, 0, Math.PI * 2);
      g.lineWidth = 1.5; g.strokeStyle = css(pal.ink, 0.85); g.stroke();
    }
  }
  g.globalAlpha = 1;

  /* axis ticks and names along the near edges, faded when an axis points at us */
  const nearX = -wx, nearZ = -wz;
  const ax = [
    { name: 'Acidity', at: (t) => [t, -1, nearZ], dir: [1, 0, 0] },
    { name: 'Body', at: (t) => [nearX, -1, -t], dir: [0, 0, -1] },
    { name: 'Sweetness', at: (t) => [wx, t, nearZ], dir: [0, 1, 0] },
  ];
  g.font = '500 10px ui-monospace, Menlo, monospace';
  g.textBaseline = 'middle';
  const c0 = project(0, 0, 0); const ccx = c0[0], ccy = c0[1];
  /* where two axes meet at a corner, the first label placed wins */
  const placed = [];
  const free = (x, y, w, h = 10, keep = true) => {
    for (const r of placed) if (Math.abs(r[0] - x) < (r[2] + w) / 2 + 2 && Math.abs(r[1] - y) < (r[3] + h) / 2 + 1) return false;
    if (keep) placed.push([x, y, w, h]);
    return true;
  };
  for (const A of ax) {
    const p0 = project(...A.at(-1)); const x0 = p0[0], y0 = p0[1];
    const p1 = project(...A.at(1)); const x1 = p1[0], y1 = p1[1]; const len = Math.hypot(x1 - x0, y1 - y0);
    const vis = Math.max(0, Math.min(1, (len / (2 * S) - 0.25) / 0.35));
    if (vis <= 0) continue;
    for (let n = 0; n <= 10; n += 2) {
      const q = project(...A.at((n - 5) / 5));
      let dx = q[0] - ccx, dy = q[1] - ccy; const d = Math.hypot(dx, dy) || 1;
      dx /= d; dy /= d;
      const txt = String(n), tw = g.measureText(txt).width;
      const align = dx > 0.3 ? 'left' : dx < -0.3 ? 'right' : 'center';
      const tx = q[0] + dx * 9, ty = q[1] + dy * 9;
      const mid = align === 'left' ? tx + tw / 2 : align === 'right' ? tx - tw / 2 : tx;
      if (!free(mid, ty, tw)) continue;
      g.globalAlpha = vis * 0.75;
      g.fillStyle = css(pal.ink);
      g.textAlign = align;
      g.fillText(txt, tx, ty);
    }
    const m = project(...A.at(0));
    let dx = m[0] - ccx, dy = m[1] - ccy; const d = Math.hypot(dx, dy) || 1;
    dx /= d; dy /= d;
    g.globalAlpha = vis;
    g.font = '650 10px system-ui, sans-serif';
    g.textAlign = 'left';
    g.fillStyle = css(pal.ink);
    /* steep axes get a rotated name; every name is kept inside the frame */
    const label = A.name.toUpperCase(), tw = g.measureText(label).width;
    const steep = Math.abs(y1 - y0) > Math.abs(x1 - x0) * 1.7;
    g.textAlign = 'center';
    /* step outward until the name clears the tick labels */
    let lx = 0, ly = 0;
    for (let off = 26; off <= 62; off += 6) {
      if (steep) {
        lx = Math.max(8, Math.min(W - 8, m[0] + dx * off));
        ly = Math.max(tw / 2 + 6, Math.min(H - tw / 2 - 6, m[1] + dy * off * 0.4));
        if (free(lx, ly, 11, tw, false)) break;
      } else {
        lx = Math.max(tw / 2 + 6, Math.min(W - tw / 2 - 6, m[0] + dx * off));
        ly = Math.max(10, Math.min(H - 8, m[1] + dy * off * 0.85));
        if (free(lx, ly, tw, 11, false)) break;
      }
    }
    if (steep) { g.save(); g.translate(lx, ly); g.rotate(-Math.PI / 2); g.fillText(label, 0, 0); g.restore(); }
    else g.fillText(label, lx, ly);
    g.font = '500 10px ui-monospace, Menlo, monospace';
  }
  g.globalAlpha = 1;
  placeTip();
}

/* ── tooltip ── */
const tk = (k) => root.querySelector('[data-k="' + k + '"]');
const tEls = { name: tk('tname'), region: tk('tregion'), a: tk('ta'), b: tk('tb'), s: tk('ts'), score: tk('tscore') };
let tipFor = -1;
function placeTip() {
  const i = hover >= 0 ? hover : pick;
  if (i < 0 || P[i].vis < 0.5) { root.removeAttribute('data-tip'); tipFor = -1; return; }
  const p = P[i];
  if (tipFor !== i) {
    tipFor = i;
    tEls.name.textContent = p.name;
    tEls.region.textContent = REGIONS[p.r];
    tEls.a.textContent = p.a.toFixed(1);
    tEls.b.textContent = p.b.toFixed(1);
    tEls.s.textContent = p.s.toFixed(1);
    tEls.score.textContent = p.score.toFixed(2);
    tip.style.setProperty('--tc', 'var(--fxd-scatter-s' + (p.r + 1) + ')');
  }
  const tw = tip.offsetWidth, th = tip.offsetHeight;
  let x = p.sx + 12, y = p.sy - th - 10, ox = '0', oy = '100%';
  if (x + tw > W - 4) { x = p.sx - tw - 12; ox = '100%'; }
  if (y < 4) { y = p.sy + 12; oy = '0'; }
  x = Math.max(4, Math.min(W - tw - 4, x));
  tip.style.translate = x.toFixed(1) + 'px ' + y.toFixed(1) + 'px';
  tip.style.setProperty('--ox', ox); tip.style.setProperty('--oy', oy);
  root.setAttribute('data-tip', '');
}

function nearest(mx, my) {
  let best = -1, bd = 16 * 16;
  for (let i = 0; i < P.length; i++) {
    const p = P[i];
    if (p.vis < 0.5) continue;
    const d = (p.sx - mx) ** 2 + (p.sy - my) ** 2;
    if (d < bd || (d === bd && best >= 0 && p.sz > P[best].sz)) { bd = d; best = i; }
  }
  return best;
}

/* ── loop: turntable at rest, camera tweens, legend fades, inertia ── */
const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
function busy(now) {
  const fading = P.some((p) => Math.abs(p.vis - (hidden.has(p.r) ? 0 : 1)) > 0.004);
  const spinning = view === 'orbit' && !calm.matches && !drag && now - lastInput > 4000;
  const settling = view === 'orbit' && Math.abs(cam.zoom - VIEWS.orbit.zoom) + Math.abs(cam.persp - VIEWS.orbit.persp) > 0.002;
  return tween || fading || spinning || settling || Math.abs(vy) + Math.abs(vp) > 0.0004;
}
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = Math.min(0.05, (now - (last || now)) / 1000);
  last = now;
  if (tween) {
    const t = Math.min(1, (now - tween.t0) / tween.dur), e = ease(t);
    cam.yaw = tween.from.yaw + (tween.to.yaw - tween.from.yaw) * e;
    cam.pitch = tween.from.pitch + (tween.to.pitch - tween.from.pitch) * e;
    cam.persp = tween.from.persp + (tween.to.persp - tween.from.persp) * e;
    cam.zoom = tween.from.zoom + (tween.to.zoom - tween.from.zoom) * e;
    if (t >= 1) tween = null;
  } else if (!drag) {
    if (Math.abs(vy) + Math.abs(vp) > 0.0004) {
      cam.yaw += vy; cam.pitch = Math.max(-0.15, Math.min(1.5, cam.pitch + vp));
      vy *= Math.pow(0.9, dt * 60); vp *= Math.pow(0.9, dt * 60);
    } else if (view === 'orbit' && !calm.matches && now - lastInput > 4000) {
      cam.yaw += dt * 0.16 * Math.min(1, (now - lastInput - 4000) / 1500);
    }
  }
  if (!tween && view === 'orbit') {
    const e = calm.matches ? 1 : 1 - Math.exp(-dt * 6);
    cam.zoom += (VIEWS.orbit.zoom - cam.zoom) * e;
    cam.persp += (VIEWS.orbit.persp - cam.persp) * e;
  }
  for (const p of P) {
    const t = hidden.has(p.r) ? 0 : 1;
    p.vis += (t - p.vis) * (calm.matches ? 1 : 1 - Math.exp(-dt * 9));
    if (Math.abs(t - p.vis) < 0.004) p.vis = t;
  }
  draw();
  if (seen && busy(now)) raf = requestAnimationFrame(frame);
}
function kick() { if (!raf && seen) { last = 0; raf = requestAnimationFrame(frame); } }

function setView(name) {
  view = name;
  viewBtns.forEach((b) => b.setAttribute('aria-pressed', b.dataset.view === name ? 'true' : 'false'));
  planeEl.textContent = VIEWS[name].label;
  const to = { ...VIEWS[name] };
  /* go the short way round */
  const twoPi = Math.PI * 2;
  to.yaw = cam.yaw + ((((to.yaw - cam.yaw) % twoPi) + 3 * Math.PI) % twoPi - Math.PI);
  vy = vp = 0;
  if (calm.matches) { Object.assign(cam, { yaw: to.yaw, pitch: to.pitch, persp: to.persp, zoom: to.zoom }); tween = null; draw(); return; }
  tween = { from: { ...cam }, to, t0: performance.now(), dur: 750 };
  lastInput = performance.now();
  kick();
}
viewBtns.forEach((b) => b.addEventListener('click', () => setView(b.dataset.view)));

function toOrbit() {
  if (view === 'orbit') return;
  view = 'orbit';
  viewBtns.forEach((b) => b.setAttribute('aria-pressed', b.dataset.view === 'orbit' ? 'true' : 'false'));
  planeEl.textContent = VIEWS.orbit.label;
  /* zoom and perspective ease back in frame(), so leaving a flat view never jumps */
}

legendBtns.forEach((b) => b.addEventListener('click', () => {
  const r = Number(b.dataset.r);
  if (hidden.has(r)) hidden.delete(r); else hidden.add(r);
  b.setAttribute('aria-pressed', hidden.has(r) ? 'false' : 'true');
  const shown = P.filter((p) => !hidden.has(p.r)).length;
  shownEl.textContent = shown;
  sr.textContent = REGIONS[r] + (hidden.has(r) ? ' hidden. ' : ' shown. ') + shown + ' of ' + P.length + ' lots visible.';
  if (pick >= 0 && hidden.has(P[pick].r)) pick = -1;
  kick();
}));

/* ── pointer ── */
function local(e) { const r = plot.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; }
plot.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const [x, y] = local(e);
  drag = { id: e.pointerId, x, y, sx: x, sy: y, moved: false, t: performance.now() };
  plot.setPointerCapture(e.pointerId);
  tween = null; vy = vp = 0;
  lastInput = performance.now();
});
plot.addEventListener('pointermove', (e) => {
  const [x, y] = local(e);
  if (drag && e.pointerId === drag.id) {
    const dx = x - drag.x, dy = y - drag.y;
    if (!drag.moved && Math.hypot(x - drag.sx, y - drag.sy) > 4) { drag.moved = true; root.setAttribute('data-drag', ''); toOrbit(); }
    if (drag.moved) {
      const now = performance.now(), dtm = Math.max(8, now - drag.t);
      cam.yaw += dx * 0.011;
      cam.pitch = Math.max(-0.15, Math.min(1.5, cam.pitch + dy * 0.009));
      vy = (dx * 0.011) * 16 / dtm; vp = (dy * 0.009) * 16 / dtm;
      drag.t = now;
      hover = -1;
      draw();
      kick();
    }
    drag.x = x; drag.y = y;
    lastInput = performance.now();
    return;
  }
  const h = nearest(x, y);
  if (h !== hover) { hover = h; root.toggleAttribute('data-hover', h >= 0); draw(); }
});
function up(e) {
  if (!drag || e.pointerId !== drag.id) return;
  const d = drag; drag = null;
  root.removeAttribute('data-drag');
  if (!d.moved) {
    const [x, y] = local(e);
    const h = nearest(x, y);
    pick = h === pick ? -1 : h;
    if (pick >= 0) announce(pick);
    draw();
  } else if (!calm.matches) kick();
  else vy = vp = 0;
}
plot.addEventListener('pointerup', up);
plot.addEventListener('pointercancel', up);
plot.addEventListener('pointerleave', () => { if (hover >= 0) { hover = -1; root.removeAttribute('data-hover'); draw(); } });

/* ── keyboard ── */
function announce(i) {
  const p = P[i];
  sr.textContent = p.name + ', ' + REGIONS[p.r] + ': acidity ' + p.a.toFixed(1) + ', body ' + p.b.toFixed(1) + ', sweetness ' + p.s.toFixed(1) + ', score ' + p.score.toFixed(2) + '.';
}
plot.addEventListener('keydown', (e) => {
  const step = 0.18;
  if (e.key === 'ArrowLeft' || e.key === 'ArrowRight' || e.key === 'ArrowUp' || e.key === 'ArrowDown') {
    toOrbit();
    const from = { ...cam }, to = { ...cam };
    if (e.key === 'ArrowLeft') to.yaw -= step;
    if (e.key === 'ArrowRight') to.yaw += step;
    if (e.key === 'ArrowUp') to.pitch = Math.min(1.5, to.pitch + step);
    if (e.key === 'ArrowDown') to.pitch = Math.max(-0.15, to.pitch - step);
    lastInput = performance.now();
    if (calm.matches) { Object.assign(cam, to); draw(); }
    else { tween = { from, to, t0: performance.now(), dur: 260 }; kick(); }
  } else if (e.key === ']' || e.key === '[') {
    const vis = P.map((p, i) => i).filter((i) => !hidden.has(P[i].r));
    if (!vis.length) return;
    const at = vis.indexOf(pick), dir = e.key === ']' ? 1 : -1;
    pick = at < 0 ? vis[dir > 0 ? 0 : vis.length - 1] : vis[(at + dir + vis.length) % vis.length];
    announce(pick);
    draw();
  } else if (e.key === 'Escape') {
    pick = -1; draw();
  } else return;
  e.preventDefault();
});

theme();
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  resize();
});
ro.observe(cv);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  seen = entries[0].isIntersecting;
  if (seen) { draw(); kick(); }
});
io.observe(root);

css:
/* Return depth is one registered length on the sign. Each glyph is fifteen
   translateZ copies plus a face, all placed at a fraction of that length,
   so changing the depth transitions every layer together as a solid. */
@property --fxd-extrude-depth { syntax: "<length>"; inherits: true; initial-value: 0px; }

.fxd-extrude {
  /* Re-theme with these four. */
  --fxd-extrude-wall: oklch(0.905 0.024 78);
  --fxd-extrude-face: oklch(0.6 0.2 29);
  --fxd-extrude-ink: oklch(0.26 0.025 45);
  --fxd-extrude-halo: oklch(0.93 0.1 86);

  --fxd-extrude-ret-lo: color-mix(in oklch, var(--fxd-extrude-face) 52%, black);
  --fxd-extrude-ret-hi: color-mix(in oklch, var(--fxd-extrude-face) 78%, black);
  --fxd-extrude-trim: color-mix(in oklch, var(--fxd-extrude-face) 70%, white);
  --fxd-extrude-shadow: color-mix(in oklch, var(--fxd-extrude-ink) 55%, transparent);
  --fxd-extrude-muted: color-mix(in oklch, var(--fxd-extrude-ink) 60%, var(--fxd-extrude-wall));
  --fxd-extrude-line: color-mix(in oklch, var(--fxd-extrude-ink) 14%, transparent);
  --fxd-extrude-card: color-mix(in oklch, var(--fxd-extrude-wall) 55%, white);
  --fxd-extrude-spring: linear(0, 0.009, 0.035 2.1%, 0.141, 0.281 6.7%, 0.723 12.9%, 0.938 16.7%, 1.017, 1.077, 1.121, 1.149 24.3%, 1.159, 1.163, 1.161, 1.154 29.9%, 1.129 32.8%, 1.051 39.6%, 1.017 43.1%, 0.991, 0.977 51%, 0.974 53.8%, 0.975 57.1%, 0.997 69.8%, 1.003 76.9%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  gap: 10px;
  box-sizing: border-box;
  inline-size: 100%;
  padding: 10px 10px 12px;
  border-radius: 18px;
  background: var(--fxd-extrude-card);
  color: var(--fxd-extrude-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxd-extrude-line);
  transition: background-color .6s, color .6s;

  /* ── stage ── */
  & .fxd-extrude__stage {
    position: relative;
    aspect-ratio: 16 / 9;
    min-block-size: 150px;
    max-block-size: 260px;
    border-radius: 12px;
    overflow: hidden;
    perspective: 100cqi;
    background: var(--fxd-extrude-wall);
    outline: none;
    cursor: crosshair;
    touch-action: pan-y;
    transition: background-color .6s;
  }
  & .fxd-extrude__stage:focus-visible { box-shadow: 0 0 0 2px var(--fxd-extrude-card), 0 0 0 4px var(--fxd-extrude-ink); }
  & .fxd-extrude__rig {
    position: absolute;
    inset: 0;
    transform-style: preserve-3d;
    transform: rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg));
  }
  & .fxd-extrude__wall {
    position: absolute;
    inset: -30%;
    transform: translateZ(-1px);
    background:
      radial-gradient(70% 60% at 30% 25%, color-mix(in oklch, var(--fxd-extrude-wall) 70%, white), transparent 70%),
      linear-gradient(transparent 70%, color-mix(in oklch, var(--fxd-extrude-ink) 10%, transparent)),
      var(--fxd-extrude-wall);
    transition: background-color .6s;
  }
  & .fxd-extrude__plaster {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    opacity: .55;
    mix-blend-mode: multiply;
  }

  & .fxd-extrude__sign {
    --fxd-extrude-depth: calc(var(--in, 4) * .07em);
    position: absolute;
    left: 50%;
    top: 58%;
    display: flex;
    translate: -50% -50%;
    transform-style: preserve-3d;
    font-family: system-ui, sans-serif;
    font-size: min(24cqi, calc(108cqi / var(--len, 6)));
    font-weight: 900;
    line-height: .86;
    letter-spacing: -.01em;
    white-space: pre;
    transition: --fxd-extrude-depth .7s var(--fxd-extrude-spring);
  }
  & .fxd-extrude__g {
    position: relative;
    display: block;
    margin-inline: .025em;
    transform-style: preserve-3d;
    transition: opacity .35s, translate .7s var(--fxd-extrude-spring);
    transition-delay: calc(var(--d, 0) * 55ms);
  }
  @starting-style {
    & .fxd-extrude__g { opacity: 0; translate: 0 -.45em; }
  }
  & .fxd-extrude__g--sp { inline-size: .28em; }
  & .fxd-extrude__f,
  & .fxd-extrude__l,
  & .fxd-extrude__sh { display: block; }
  & .fxd-extrude__f {
    position: relative;
    color: transparent;
    background: linear-gradient(170deg, color-mix(in oklch, var(--fxd-extrude-face) 78%, white) 0%, var(--fxd-extrude-face) 45%, color-mix(in oklch, var(--fxd-extrude-face) 88%, black) 100%);
    -webkit-background-clip: text;
    background-clip: text;
    transform: translateZ(var(--fxd-extrude-depth));
  }
  & .fxd-extrude__l {
    position: absolute;
    inset: 0;
    color: color-mix(in oklch, var(--fxd-extrude-ret-hi) calc(var(--k) * 6.67%), var(--fxd-extrude-ret-lo));
    transform: translateZ(calc(var(--fxd-extrude-depth) * var(--k) / 15.5));
    transition: color .6s;
  }
  /* the trim cap: a lighter rim right behind the face */
  & .fxd-extrude__l--trim { color: var(--fxd-extrude-trim); }
  & .fxd-extrude__sh {
    position: absolute;
    inset: 0;
    color: var(--fxd-extrude-shadow);
    translate: calc(var(--fxd-extrude-depth) * .55) calc(var(--fxd-extrude-depth) * .85);
    filter: blur(calc(var(--fxd-extrude-depth) * .35 + 1px));
    transition: color .6s, translate .6s, filter .6s;
  }

  /* ── night: halo-lit letters, the light is on the wall behind them ── */
  &:has(.fxd-extrude__night input:checked) {
    --fxd-extrude-card: color-mix(in oklch, var(--fxd-extrude-ink) 92%, black);
    --fxd-extrude-line: color-mix(in oklch, var(--fxd-extrude-halo) 14%, transparent);
    --fxd-extrude-muted: color-mix(in oklch, var(--fxd-extrude-halo) 55%, var(--fxd-extrude-ink));
    color: color-mix(in oklch, var(--fxd-extrude-halo) 90%, white);

    & .fxd-extrude__stage { background: color-mix(in oklch, var(--fxd-extrude-ink) 78%, black); }
    & .fxd-extrude__wall {
      background:
        radial-gradient(55% 45% at 50% 58%, color-mix(in oklch, var(--fxd-extrude-halo) 24%, transparent), transparent 75%),
        color-mix(in oklch, var(--fxd-extrude-ink) 82%, black);
    }
    & .fxd-extrude__plaster { opacity: .3; }
    & .fxd-extrude__f { background: linear-gradient(170deg, oklch(0.36 0.02 45), oklch(0.22 0.02 45)); -webkit-background-clip: text; background-clip: text; }
    /* returns pick up the halo where they meet the wall */
    & .fxd-extrude__l { color: color-mix(in oklch, oklch(0.2 0.015 45) calc(52% + var(--k) * 3.2%), var(--fxd-extrude-halo)); }
    & .fxd-extrude__l--trim { color: oklch(0.3 0.02 45); }
    & .fxd-extrude__sh {
      color: var(--fxd-extrude-halo);
      translate: 0 0;
      filter: blur(calc(var(--fxd-extrude-depth) * .6 + 4px)) brightness(1.25);
    }
    & .fxd-extrude__g:nth-child(2) .fxd-extrude__sh { animation: fxd-extrude-flicker 6.5s steps(1, end) infinite; }
    & .fxd-extrude__head { color: color-mix(in oklch, var(--fxd-extrude-halo) 92%, white); }
  }

  &[data-off] .fxd-extrude__sh { animation-play-state: paused; }

  & .fxd-extrude__head {
    position: absolute;
    left: 22px;
    top: 20px;
    pointer-events: none;
    transition: color .6s;
  }
  & .fxd-extrude__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--fxd-extrude-muted);
  }
  & .fxd-extrude__title {
    margin: 2px 0 0;
    font-size: clamp(14px, 4.6cqi, 18px);
    font-weight: 700;
    letter-spacing: -.01em;
    text-wrap: balance;
  }

  /* ── controls ── */
  & .fxd-extrude__form {
    display: grid;
    grid-template-areas: "text night" "depth depth";
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px;
  }
  & .fxd-extrude__text {
    grid-area: text;
    display: flex;
    align-items: center;
    gap: 8px;
    min-inline-size: 0;
    padding: 0 4px 0 12px;
    border-radius: 10px;
    background: color-mix(in oklch, var(--fxd-extrude-ink) 6%, transparent);
    box-shadow: inset 0 0 0 1px var(--fxd-extrude-line);
    transition: box-shadow .2s, background-color .6s;
  }
  & .fxd-extrude__text:has(input:focus-visible) { box-shadow: inset 0 0 0 2px var(--fxd-extrude-face); }
  & .fxd-extrude__text span,
  & .fxd-extrude__depth > span {
    font-size: 10px;
    font-weight: 650;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--fxd-extrude-muted);
  }
  & .fxd-extrude__text input {
    flex: 1;
    min-inline-size: 0;
    block-size: 36px;
    padding: 0;
    border: 0;
    background: transparent;
    color: inherit;
    font: 700 15px/1 ui-monospace, Menlo, monospace;
    letter-spacing: .14em;
    text-transform: uppercase;
    outline: none;
  }
  & .fxd-extrude__night {
    grid-area: night;
    position: relative;
    display: grid;
    place-items: center;
    inline-size: 52px;
    block-size: 36px;
    border-radius: 10px;
    background: color-mix(in oklch, var(--fxd-extrude-ink) 6%, transparent);
    box-shadow: inset 0 0 0 1px var(--fxd-extrude-line);
    cursor: pointer;
    transition: background-color .3s, box-shadow .2s;
  }
  & .fxd-extrude__night input {
    position: absolute;
    inset: 0;
    margin: 0;
    opacity: 0;
    cursor: pointer;
  }
  & .fxd-extrude__night:has(:focus-visible) { box-shadow: inset 0 0 0 2px var(--fxd-extrude-face); }
  & .fxd-extrude__night:has(:checked) { background: color-mix(in oklch, var(--fxd-extrude-halo) 22%, transparent); }
  & .fxd-extrude__night svg {
    inline-size: 18px;
    block-size: 18px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.4;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxd-extrude__moon { display: none; }
  & .fxd-extrude__night:has(:checked) .fxd-extrude__moon { display: inline; fill: currentColor; }
  & .fxd-extrude__night:has(:checked) .fxd-extrude__sun { display: none; }

  & .fxd-extrude__depth {
    grid-area: depth;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) 5ch;
    align-items: center;
    gap: 10px;
    padding-inline: 4px;
  }
  & .fxd-extrude__depth input {
    margin: 0;
    accent-color: var(--fxd-extrude-face);
    cursor: ew-resize;
  }
  & .fxd-extrude__depth input:focus-visible { outline: 2px solid var(--fxd-extrude-face); outline-offset: 2px; border-radius: 4px; }
  & .fxd-extrude__depth output {
    text-align: end;
    font: 600 12px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxd-extrude__quote {
    display: flex;
    align-items: baseline;
    gap: 6px;
    margin: 0;
    padding: 8px 4px 0;
    border-block-start: 1px solid var(--fxd-extrude-line);
    font: 500 12px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxd-extrude-muted);
  }
  & .fxd-extrude__quote b {
    margin-inline-start: auto;
    font-size: 15px;
    font-weight: 700;
    color: inherit;
    color: var(--fxd-extrude-face);
  }
  & .fxd-extrude__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @container (min-width: 440px) {
    & .fxd-extrude__form {
      grid-template-areas: "text depth night";
      grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr) auto;
    }
  }
}

/* a tired LED module, as real halo signs have */
@keyframes fxd-extrude-flicker {
  0%, 61%, 63.5%, 66%, 100% { opacity: 1; }
  62%, 64.5% { opacity: .35; }
  65% { opacity: .7; }
}

@media (prefers-reduced-motion: reduce) {
  .fxd-extrude .fxd-extrude__sign,
  .fxd-extrude .fxd-extrude__g { transition: none; }
  .fxd-extrude .fxd-extrude__sh,
  .fxd-extrude .fxd-extrude__g:nth-child(2) .fxd-extrude__sh { animation: none; }
}

js:
/* Channel letters. Each glyph = a wall shadow, fifteen return layers and a
   face, every one a translateZ fraction of the sign's registered depth. The
   rig tilts toward the pointer on a damped spring (and drifts on its own at
   rest); typing re-letters the sign, keeping unchanged glyphs in place so
   only new ones drop in through @starting-style. */
const stage = root.querySelector('.fxd-extrude__stage');
const sign = root.querySelector('.fxd-extrude__sign');
const rig = root.querySelector('.fxd-extrude__rig');
const input = root.querySelector('.fxd-extrude__text input');
const depth = root.querySelector('.fxd-extrude__depth input');
const depthOut = root.querySelector('.fxd-extrude__depth output');
const night = root.querySelector('.fxd-extrude__night input');
const out = { count: root.querySelector('[data-k="count"]'), unit: root.querySelector('[data-k="unit"]'), total: root.querySelector('[data-k="total"]') };
const calm = matchMedia('(prefers-reduced-motion: reduce)');
const LAYERS = 15;
const BASE = 100, PER_INCH = 16;           /* $ per letter, $ per inch of return */

/* the plaster filter needs a document-unique id */
const uid = 'fxd-extrude-plaster-' + Math.random().toString(36).slice(2, 8);
const filt = root.querySelector('.fxd-extrude__plaster filter');
filt.id = uid;
root.querySelector('.fxd-extrude__plaster rect').setAttribute('filter', 'url(#' + uid + ')');

function glyph(ch, i) {
  const g = document.createElement('span');
  g.className = 'fxd-extrude__g' + (ch === ' ' ? ' fxd-extrude__g--sp' : '');
  g.dataset.ch = ch;
  g.style.setProperty('--d', i);
  if (ch === ' ') return g;
  let html = '<span class="fxd-extrude__sh">' + ch + '</span>';
  for (let k = 1; k <= LAYERS; k++) {
    html += '<span class="fxd-extrude__l' + (k === LAYERS ? ' fxd-extrude__l--trim' : '') + '" style="--k:' + k + '">' + ch + '</span>';
  }
  html += '<span class="fxd-extrude__f">' + ch + '</span>';
  g.innerHTML = html;
  return g;
}

const esc = (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c] || c);
function clean(v) {
  return v.toUpperCase().replace(/[^A-Z0-9 &!'.\-]/g, '').replace(/\s+/g, ' ').slice(0, 8);
}

function letter(text) {
  const chars = [...text];
  const kids = [...sign.children];
  let fresh = 0;
  chars.forEach((c, i) => {
    const e = esc(c);
    if (kids[i] && kids[i].dataset.ch === e) return;
    const g = glyph(e, fresh++);
    if (kids[i]) kids[i].replaceWith(g); else sign.append(g);
  });
  for (let i = chars.length; i < kids.length; i++) kids[i].remove();
  sign.style.setProperty('--len', Math.max(3, chars.length));
  quote();
}

function quote() {
  const n = [...clean(input.value)].filter((c) => c !== ' ').length;
  const inch = Number(depth.value);
  const unit = BASE + PER_INCH * inch;
  out.count.textContent = n + (n === 1 ? ' letter' : ' letters');
  out.unit.textContent = '$' + unit;
  out.total.textContent = '$' + (n * unit).toLocaleString('en-US');
  depthOut.textContent = inch + ' in';
  depth.setAttribute('aria-valuetext', inch + ' inch returns');
  const word = clean(input.value).trim() || 'nothing yet';
  stage.setAttribute('aria-label', 'Sign reading ' + word + ' in channel letters with ' + inch + ' inch returns' + (night.checked ? ', halo-lit at night' : ', in daylight'));
}

input.addEventListener('input', () => {
  const v = clean(input.value);
  if (v !== input.value) {
    const at = input.selectionStart;
    input.value = v;
    input.setSelectionRange(Math.min(at, v.length), Math.min(at, v.length));
  }
  letter(v || ' ');
});
depth.addEventListener('input', () => { sign.style.setProperty('--in', depth.value); quote(); });
night.addEventListener('change', quote);

/* ── tilt: a damped spring toward the pointer, a slow drift at rest ── */
let tx = 0, ty = 0, rx = 0, ry = 0, vx = 0, vy = 0, lastMove = -1e9, keyX = 0, keyY = 0;
let raf = 0, last = 0, seen = false;
stage.addEventListener('pointermove', (e) => {
  const r = stage.getBoundingClientRect();
  tx = ((e.clientX - r.left) / r.width - 0.5) * 2;
  ty = ((e.clientY - r.top) / r.height - 0.5) * 2;
  lastMove = performance.now();
  kick();
});
stage.addEventListener('pointerleave', () => { lastMove = performance.now() - 1500; });
stage.addEventListener('keydown', (e) => {
  const m = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[e.key];
  if (!m) { if (e.key === 'Escape' || e.key === 'Home') { keyX = keyY = 0; kick(); } return; }
  keyX = Math.max(-1, Math.min(1, keyX + m[0] * 0.5));
  keyY = Math.max(-1, Math.min(1, keyY + m[1] * 0.5));
  lastMove = performance.now() + 4000;
  if (calm.matches) { ry = keyX * 32; rx = -keyY * 20; paint(); return; }
  kick();
  e.preventDefault();
});

function paint() {
  rig.style.setProperty('--rx', rx.toFixed(2) + 'deg');
  rig.style.setProperty('--ry', ry.toFixed(2) + 'deg');
}
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = Math.min(0.033, (now - (last || now)) / 1000);
  last = now;
  const t = now / 1000;
  const idle = now - lastMove > 1600;
  const gx = idle ? Math.sin(t * 0.45) * 0.55 + keyX : tx + keyX;
  const gy = idle ? Math.sin(t * 0.31 + 0.8) * 0.4 + keyY : ty + keyY;
  const targetY = Math.max(-1.2, Math.min(1.2, gx)) * 30;
  const targetX = -Math.max(-1.2, Math.min(1.2, gy)) * 18;
  /* semi-implicit Euler spring: k = 90, c = 13 */
  vy += ((targetY - ry) * 90 - vy * 13) * dt; ry += vy * dt;
  vx += ((targetX - rx) * 90 - vx * 13) * dt; rx += vx * dt;
  paint();
  if (seen && !calm.matches) raf = requestAnimationFrame(frame);
}
function kick() {
  if (!raf && seen && !calm.matches) { last = 0; raf = requestAnimationFrame(frame); }
}

letter(clean(input.value) || ' ');
sign.style.setProperty('--in', depth.value);
quote();
if (calm.matches) { ry = -14; rx = 6; paint(); }

const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  seen = entries[0].isIntersecting;
  root.toggleAttribute('data-off', !seen);
  if (seen) kick();
});
io.observe(root);

