.fxd-sun {
  /* Re-theme with these four; the canvas reads them. */
  --fxd-sun-paper: oklch(0.962 0.01 85);
  --fxd-sun-ink: oklch(0.3 0.025 255);
  --fxd-sun-shade: oklch(0.52 0.07 258);
  --fxd-sun-sun: oklch(0.76 0.15 62);

  --fxd-sun-muted: color-mix(in oklch, var(--fxd-sun-ink) 58%, var(--fxd-sun-paper));
  --fxd-sun-line: color-mix(in oklch, var(--fxd-sun-ink) 13%, transparent);
  --fxd-sun-well: color-mix(in oklch, var(--fxd-sun-ink) 5%, var(--fxd-sun-paper));

  container-type: inline-size;
  display: grid;
  gap: 8px;
  box-sizing: border-box;
  inline-size: 100%;
  padding: 14px 14px 12px;
  border-radius: 18px;
  background: var(--fxd-sun-paper);
  color: var(--fxd-sun-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxd-sun-line);

  & .fxd-sun__head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 10px;
  }
  & .fxd-sun__head > div { min-inline-size: 0; }
  & .fxd-sun__eyebrow {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin: 0;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: .09em;
    text-transform: uppercase;
    color: var(--fxd-sun-muted);
  }
  & .fxd-sun__title {
    margin: 2px 0 0;
    font-size: clamp(17px, 6cqi, 22px);
    font-weight: 720;
    letter-spacing: -.02em;
    line-height: 1.1;
  }
  & .fxd-sun__lat {
    flex: none;
    white-space: nowrap;
    margin: 0 0 2px;
    padding: 3px 7px;
    border-radius: 6px;
    background: var(--fxd-sun-well);
    box-shadow: inset 0 0 0 1px var(--fxd-sun-line);
    font: 600 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }

  & .fxd-sun__model {
    position: relative;
    aspect-ratio: 16 / 11;
    min-block-size: 170px;
    max-block-size: 250px;
    border-radius: 12px;
    background: var(--fxd-sun-well);
    cursor: grab;
    touch-action: pan-y;
    outline: none;
  }
  &[data-drag] .fxd-sun__model { cursor: grabbing; }
  & .fxd-sun__model:focus-visible { box-shadow: 0 0 0 2px var(--fxd-sun-ink); }
  & .fxd-sun__cv {
    position: absolute;
    inset: 0;
    display: block;
    inline-size: 100%;
    block-size: 100%;
    border-radius: inherit;
  }
  & .fxd-sun__probe { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }
  & .fxd-sun__tip {
    position: absolute;
    left: 0;
    top: 0;
    display: grid;
    gap: 1px;
    margin: 0;
    padding: 6px 9px;
    border-radius: 8px;
    background: color-mix(in oklch, var(--fxd-sun-paper) 92%, transparent);
    box-shadow: 0 0 0 1px var(--fxd-sun-line), 0 8px 20px -10px color-mix(in oklch, var(--fxd-sun-ink) 45%, transparent);
    font-size: 12px;
    white-space: nowrap;
    pointer-events: none;
    opacity: 0;
    translate: var(--tx, 0) var(--ty, 0);
    transition: opacity .15s;
  }
  & .fxd-sun__tip span {
    font: 500 11px/1.2 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxd-sun-muted);
  }
  &[data-tip] .fxd-sun__tip { opacity: 1; }

  & .fxd-sun__row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 6px 10px;
  }
  & .fxd-sun__dates {
    display: inline-flex;
    margin: 0;
    padding: 2px;
    border: 0;
    border-radius: 9px;
    background: var(--fxd-sun-well);
    box-shadow: inset 0 0 0 1px var(--fxd-sun-line);
  }
  & .fxd-sun__dates label { position: relative; display: grid; cursor: pointer; }
  & .fxd-sun__dates input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & .fxd-sun__dates span {
    padding: 5px 8px;
    border-radius: 7px;
    font: 600 11px/1.1 system-ui, sans-serif;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    color: var(--fxd-sun-muted);
    transition: background-color .2s, color .2s, box-shadow .2s;
  }
  & .fxd-sun__dates label:hover span { color: var(--fxd-sun-ink); }
  & .fxd-sun__dates label:has(:checked) span {
    background: var(--fxd-sun-paper);
    color: var(--fxd-sun-ink);
    box-shadow: 0 1px 2px color-mix(in oklch, var(--fxd-sun-ink) 18%, transparent), 0 0 0 1px var(--fxd-sun-line);
  }
  & .fxd-sun__dates label:has(:focus-visible) span { outline: 2px solid var(--fxd-sun-ink); outline-offset: 1px; }

  & .fxd-sun__read {
    display: flex;
    gap: 12px;
    margin: 0;
  }
  & .fxd-sun__read div { display: grid; gap: 2px; }
  & .fxd-sun__read dt {
    font-size: 9.5px;
    font-weight: 650;
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--fxd-sun-muted);
  }
  & .fxd-sun__read dd {
    margin: 0;
    font: 500 12px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxd-sun-muted);
    white-space: nowrap;
  }
  & .fxd-sun__read b { font-size: 14px; font-weight: 650; color: var(--fxd-sun-ink); }
  & .fxd-sun__read div:last-child b { color: color-mix(in oklch, var(--fxd-sun-shade) 85%, var(--fxd-sun-ink)); }

  /* ── the day: a scrubber whose track is the plaza-shade curve ── */
  & .fxd-sun__scrub {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) 5.2ch;
    align-items: center;
    gap: 10px;
  }
  & .fxd-sun__play {
    display: grid;
    place-items: center;
    inline-size: 32px;
    block-size: 32px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: var(--fxd-sun-ink);
    color: var(--fxd-sun-paper);
    cursor: pointer;
    transition: background-color .2s, scale .3s cubic-bezier(.34, 1.56, .64, 1);
  }
  & .fxd-sun__play:hover { background: color-mix(in oklch, var(--fxd-sun-ink) 80%, var(--fxd-sun-sun)); }
  & .fxd-sun__play:active { scale: .92; }
  & .fxd-sun__play:focus-visible { outline: 2px solid var(--fxd-sun-sun); outline-offset: 2px; }
  & .fxd-sun__play svg { inline-size: 14px; block-size: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & .fxd-sun__ic-play { display: none; fill: currentColor; }
  & .fxd-sun__play[aria-pressed="false"] .fxd-sun__ic-play { display: inline; }
  & .fxd-sun__play[aria-pressed="false"] .fxd-sun__ic-pause { display: none; }

  & .fxd-sun__track {
    --thumb: 14px;
    position: relative;
    block-size: 44px;
  }
  & .fxd-sun__curve {
    position: absolute;
    left: calc(var(--thumb) / 2);
    right: calc(var(--thumb) / 2);
    top: 2px;
    inline-size: calc(100% - var(--thumb));
    block-size: 30px;
    overflow: visible;
  }
  & .fxd-sun__night { fill: color-mix(in oklch, var(--fxd-sun-ink) 8%, transparent); }
  & .fxd-sun__area { fill: color-mix(in oklch, var(--fxd-sun-shade) 20%, transparent); }
  & .fxd-sun__line { fill: none; stroke: var(--fxd-sun-shade); stroke-width: 1.5; vector-effect: non-scaling-stroke; stroke-linejoin: round; }
  & .fxd-sun__time {
    position: absolute;
    inset: 0 0 12px;
    appearance: none;
    -webkit-appearance: none;
    inline-size: 100%;
    margin: 0;
    background: linear-gradient(var(--fxd-sun-line), var(--fxd-sun-line)) 0 100% / 100% 1px no-repeat;
    accent-color: var(--fxd-sun-sun);
    cursor: ew-resize;
  }
  & .fxd-sun__time::-webkit-slider-thumb {
    -webkit-appearance: none;
    inline-size: var(--thumb);
    block-size: 32px;
    border: 0;
    background:
      radial-gradient(circle at 50% 4px, var(--fxd-sun-sun) 4px, transparent 4.5px),
      linear-gradient(var(--fxd-sun-ink), var(--fxd-sun-ink)) 50% 0 / 2px 100% no-repeat;
  }
  & .fxd-sun__time::-moz-range-thumb {
    inline-size: var(--thumb);
    block-size: 32px;
    border: 0;
    border-radius: 0;
    background:
      radial-gradient(circle at 50% 4px, var(--fxd-sun-sun) 4px, transparent 4.5px),
      linear-gradient(var(--fxd-sun-ink), var(--fxd-sun-ink)) 50% 0 / 2px 100% no-repeat;
  }
  & .fxd-sun__time:focus-visible { outline: 2px solid var(--fxd-sun-ink); outline-offset: 2px; border-radius: 4px; }
  & .fxd-sun__hours {
    position: absolute;
    inset: auto calc(var(--thumb) / 2) 0;
    block-size: 10px;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  & .fxd-sun__hours li {
    position: absolute;
    left: calc((var(--h) * 60 - 240) / 990 * 100%);
    translate: -50% 0;
    font: 500 9.5px/1 ui-monospace, Menlo, monospace;
    color: var(--fxd-sun-muted);
  }
  & .fxd-sun__clock {
    text-align: end;
    font: 650 14px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxd-sun__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxd-sun .fxd-sun__play,
  .fxd-sun .fxd-sun__dates span,
  .fxd-sun .fxd-sun__tip { transition: none; }
}

js:
/* Sun study. Solar altitude/azimuth come from latitude, declination and hour
   angle (local solar time). Each block's ground shadow is the convex hull of
   its footprint and its roof pushed along the sun vector by h / tan(alt).
   The plaza figure is measured, not estimated: the same hulls are filled
   into a 1 px = 1 m plan raster and the shaded plaza pixels are counted, so
   the readout, the day curve and the drawing all come from one geometry. */
const model = root.querySelector('.fxd-sun__model');
const cv = root.querySelector('.fxd-sun__cv');
const ctx = cv.getContext('2d');
const probe = root.querySelector('.fxd-sun__probe');
const tipEl = root.querySelector('.fxd-sun__tip');
const range = root.querySelector('.fxd-sun__time');
const clock = root.querySelector('.fxd-sun__clock');
const playBtn = root.querySelector('.fxd-sun__play');
const radios = [...root.querySelectorAll('.fxd-sun__dates input')];
const k = (n) => root.querySelector('[data-k="' + n + '"]');
const out = { alt: k('alt'), az: k('az'), shade: k('shade'), bname: k('bname'), bmeta: k('bmeta') };
const paths = { night: root.querySelector('.fxd-sun__night'), area: root.querySelector('.fxd-sun__area'), line: root.querySelector('.fxd-sun__line') };
const calm = matchMedia('(prefers-reduced-motion: reduce)');
if (!ctx) return;

const D = Math.PI / 180, LAT = 52 * D, STOREY = 3.5;
const T0 = 240, T1 = 1230;                         /* 04:00 … 20:30 */
/* plan metres: x east, y south; the site is 100 × 100 m centred on 0 */
const BLOCKS = [
  { name: 'Quay Tower', x0: -44, y0: 20, x1: -26, y1: 40, fl: 14 },
  { name: 'Ropewalk House', x0: -46, y0: -44, x1: -24, y1: -8, fl: 6 },
  { name: 'Net Loft', x0: 22, y0: -40, x1: 46, y1: -6, fl: 4 },
  { name: 'Chandlery', x0: 24, y0: 8, x1: 46, y1: 40, fl: 3 },
  { name: 'Harbour Hall', x0: -8, y0: 32, x1: 16, y1: 46, fl: 5 },
].map((b) => ({ ...b, h: b.fl * STOREY }));
const PLAZA = { x0: -18, y0: -30, x1: 16, y1: 24 };   /* 34 × 54 m = 1,836 m² */

uidRadios();
function uidRadios() {
  const n = 'fxd-sun-date-' + Math.random().toString(36).slice(2, 8);
  radios.forEach((r) => { r.name = n; });
}

/* ── sun ── */
function solar(min, decl) {
  const H = (min / 60 - 12) * 15 * D, d = decl * D;
  const sinAlt = Math.sin(LAT) * Math.sin(d) + Math.cos(LAT) * Math.cos(d) * Math.cos(H);
  const alt = Math.asin(Math.max(-1, Math.min(1, sinAlt)));
  const az = Math.atan2(Math.sin(H), Math.cos(H) * Math.sin(LAT) - Math.tan(d) * Math.cos(LAT)) + Math.PI;
  return { alt, az };
}
const sunVec = (s) => [Math.cos(s.alt) * Math.sin(s.az), -Math.cos(s.alt) * Math.cos(s.az), Math.sin(s.alt)];

function hull(pts) {
  pts.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cross = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lo = [], up = [];
  for (const p of pts) { while (lo.length > 1 && cross(lo[lo.length - 2], lo[lo.length - 1], p) <= 0) lo.pop(); lo.push(p); }
  for (let i = pts.length - 1; i >= 0; i--) { const p = pts[i]; while (up.length > 1 && cross(up[up.length - 2], up[up.length - 1], p) <= 0) up.pop(); up.push(p); }
  return lo.slice(0, -1).concat(up.slice(0, -1));
}
function shadowOf(b, s) {
  const L = Math.min(600, b.h / Math.tan(s.alt));
  const dx = -Math.sin(s.az) * L, dy = Math.cos(s.az) * L;
  const c = [[b.x0, b.y0], [b.x1, b.y0], [b.x1, b.y1], [b.x0, b.y1]];
  return hull(c.concat(c.map(([x, y]) => [x + dx, y + dy])));
}

/* plan raster for the measurement */
const an = document.createElement('canvas');
an.width = an.height = 100;
const ax = an.getContext('2d', { willReadFrequently: true });
const PW = PLAZA.x1 - PLAZA.x0, PH = PLAZA.y1 - PLAZA.y0;
function plazaShade(s) {
  if (s.alt <= 0.002) return null;
  ax.clearRect(0, 0, 100, 100);
  ax.fillStyle = '#000';
  for (const b of BLOCKS) {
    const p = shadowOf(b, s);
    ax.beginPath();
    p.forEach(([x, y], i) => (i ? ax.lineTo(x + 50, y + 50) : ax.moveTo(x + 50, y + 50)));
    ax.fill();
  }
  const d = ax.getImageData(PLAZA.x0 + 50, PLAZA.y0 + 50, PW, PH).data;
  let n = 0;
  for (let i = 3; i < d.length; i += 4) if (d[i] > 127) n++;
  return n / (PW * PH);
}

/* ── the day curve for the chosen date ── */
let decl = 0, curve = [], rise = T0, set = T1;
function buildCurve() {
  curve = [];
  for (let m = T0; m <= T1; m += 15) curve.push(plazaShade(solar(m, decl)));
  const X = (m) => ((m - T0) / (T1 - T0)) * 660;
  const Y = (v) => 38 - v * 36;
  let line = '', area = '', night = '', run = null;
  curve.forEach((v, i) => {
    const m = T0 + i * 15;
    if (v === null) {
      night += 'M' + Math.max(0, X(m) - 5).toFixed(1) + ' 0h10V40h-10Z';
      if (run) { area += 'L' + X(run.last).toFixed(1) + ' 38Z'; run = null; }
      return;
    }
    if (!run) { run = { last: m }; line += 'M'; area += 'M' + X(m).toFixed(1) + ' 38L'; } else { line += 'L'; area += 'L'; }
    line += X(m).toFixed(1) + ' ' + Y(v).toFixed(1);
    area += X(m).toFixed(1) + ' ' + Y(v).toFixed(1);
    run.last = m;
  });
  if (run) area += 'L' + X(run.last).toFixed(1) + ' 38Z';
  paths.line.setAttribute('d', line);
  paths.area.setAttribute('d', area);
  paths.night.setAttribute('d', night);
  /* the auto-play loop runs from half an hour before sunrise to half after sunset */
  let a = T0, z = T1;
  for (let m = T0; m <= T1; m += 5) if (solar(m, decl).alt > 0) { a = m; break; }
  for (let m = T1; m >= T0; m -= 5) if (solar(m, decl).alt > 0) { z = m; break; }
  rise = Math.max(T0, a - 30); set = Math.min(T1, z + 30);
}

/* ── palette ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const pal = {};
const mix = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
const css = (c, a = 1) => 'rgba(' + (c[0] | 0) + ',' + (c[1] | 0) + ',' + (c[2] | 0) + ',' + a + ')';
function theme() {
  pal.paper = rgb('--fxd-sun-paper');
  pal.ink = rgb('--fxd-sun-ink');
  pal.shade = rgb('--fxd-sun-shade');
  pal.sun = rgb('--fxd-sun-sun');
  pal.white = mix(pal.paper, [255, 255, 255], 0.75);
  pal.ground = mix(pal.paper, pal.ink, 0.07);
  pal.stone = mix(mix(pal.paper, pal.sun, 0.16), pal.ink, 0.04);
}

/* ── view ── */
let W = 0, H = 0, DPR = 1, S = 1, CX = 0, CY = 0;
let yaw = 0.62, elev = 0.62, minutes = 900, playing = !calm.matches, seen = false, raf = 0, last = 0;
let hoverB = -1, hulls = [];
const shadowCv = document.createElement('canvas');
const sx = shadowCv.getContext('2d');

function resize() {
  const r = cv.getBoundingClientRect();
  if (!r.width || !r.height) return;
  W = r.width; H = r.height;
  DPR = Math.min(2, window.devicePixelRatio || 1);
  cv.width = shadowCv.width = Math.round(W * DPR);
  cv.height = shadowCv.height = Math.round(H * DPR);
  S = Math.min(W / 176, H / 132);
  CX = W / 2; CY = H * 0.56;
  draw();
}
let cyaw = 1, syaw = 0, se = 0, ce = 1;
function proj(x, y, z) {
  const xr = x * cyaw - y * syaw, yr = x * syaw + y * cyaw;
  return [CX + xr * S, CY + yr * S * se - z * S * ce, yr];
}

/* how much of a face is in another block's shadow: march sample points toward the sun */
function shadowed(px, py, pz, v, self) {
  for (let i = 0; i < BLOCKS.length; i++) {
    if (i === self) continue;
    const b = BLOCKS[i];
    let t0 = 0.01, t1 = 1e4;
    const lo = [b.x0, b.y0, 0], hi = [b.x1, b.y1, b.h], o = [px, py, pz];
    let hit = true;
    for (let a = 0; a < 3; a++) {
      if (Math.abs(v[a]) < 1e-9) { if (o[a] < lo[a] || o[a] > hi[a]) { hit = false; break; } continue; }
      let ta = (lo[a] - o[a]) / v[a], tb = (hi[a] - o[a]) / v[a];
      if (ta > tb) [ta, tb] = [tb, ta];
      t0 = Math.max(t0, ta); t1 = Math.min(t1, tb);
      if (t0 > t1) { hit = false; break; }
    }
    if (hit) return true;
  }
  return false;
}
function faceShade(corners, v, self) {
  let n = 0, inS = 0;
  for (let u = 0.17; u < 1; u += 0.33) for (let w = 0.17; w < 1; w += 0.33) {
    const [a, b, , d] = corners;
    const px = a[0] + (b[0] - a[0]) * u + (d[0] - a[0]) * w;
    const py = a[1] + (b[1] - a[1]) * u + (d[1] - a[1]) * w;
    const pz = a[2] + (b[2] - a[2]) * u + (d[2] - a[2]) * w;
    n++; if (shadowed(px, py, pz, v, self)) inS++;
  }
  return inS / n;
}

function poly(g, pts) {
  g.beginPath();
  pts.forEach((p, i) => (i ? g.lineTo(p[0], p[1]) : g.moveTo(p[0], p[1])));
  g.closePath();
}

function draw() {
  if (!W || !pal.paper) return;
  cyaw = Math.cos(yaw); syaw = Math.sin(yaw); se = Math.sin(elev); ce = Math.cos(elev);
  const s = solar(minutes, decl);
  const v = sunVec(s);
  const day = Math.max(0, Math.min(1, s.alt / (7 * D)));
  const g = ctx;
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  g.clearRect(0, 0, W, H);

  /* sky wash: pale by day, warm near the horizon, cool at night */
  const sky = g.createLinearGradient(0, 0, 0, H);
  const warm = mix(pal.paper, pal.sun, 0.35 * (1 - Math.min(1, s.alt / (25 * D))) * day);
  sky.addColorStop(0, css(mix(mix(pal.paper, pal.shade, 0.55), warm, day)));
  sky.addColorStop(1, css(mix(mix(pal.paper, pal.ink, 0.3), pal.paper, day)));
  g.fillStyle = sky;
  g.fillRect(0, 0, W, H);

  sunPath(g, s, v, false);

  /* the model's base slab */
  const site = [[-50, -50], [50, -50], [50, 50], [-50, 50]];
  const top = site.map(([x, y]) => proj(x, y, 0));
  const bot = site.map(([x, y]) => proj(x, y, -3));
  const dim = (c) => mix(mix(c, pal.shade, 0.45), c, day);
  for (let i = 0; i < 4; i++) {
    const j = (i + 1) % 4;
    const nx = site[j][1] - site[i][1], ny = site[i][0] - site[j][0];
    if (nx * syaw + ny * cyaw <= 0) continue;
    poly(g, [top[i], top[j], bot[j], bot[i]]);
    g.fillStyle = css(mix(dim(pal.ground), pal.ink, 0.18)); g.fill();
  }
  poly(g, top);
  g.fillStyle = css(dim(pal.ground)); g.fill();

  /* plaza paving with a 6 m joint grid */
  const pz = [[PLAZA.x0, PLAZA.y0], [PLAZA.x1, PLAZA.y0], [PLAZA.x1, PLAZA.y1], [PLAZA.x0, PLAZA.y1]].map(([x, y]) => proj(x, y, 0));
  poly(g, pz);
  g.fillStyle = css(dim(pal.stone)); g.fill();
  g.beginPath();
  for (let x = PLAZA.x0 + 6; x < PLAZA.x1; x += 6) { const a = proj(x, PLAZA.y0, 0), b = proj(x, PLAZA.y1, 0); g.moveTo(a[0], a[1]); g.lineTo(b[0], b[1]); }
  for (let y = PLAZA.y0 + 6; y < PLAZA.y1; y += 6) { const a = proj(PLAZA.x0, y, 0), b = proj(PLAZA.x1, y, 0); g.moveTo(a[0], a[1]); g.lineTo(b[0], b[1]); }
  g.strokeStyle = css(pal.ink, 0.07); g.lineWidth = 1; g.stroke();

  /* ground shadows: one opaque pass offscreen, composited once, so overlaps don't double up */
  if (s.alt > 0.002) {
    sx.setTransform(DPR, 0, 0, DPR, 0, 0);
    sx.clearRect(0, 0, W, H);
    sx.fillStyle = '#000';
    for (const b of BLOCKS) { poly(sx, shadowOf(b, s).map(([x, y]) => proj(x, y, 0))); sx.fill(); }
    sx.globalCompositeOperation = 'source-in';
    sx.fillStyle = css(pal.shade);
    sx.fillRect(0, 0, W, H);
    sx.globalCompositeOperation = 'source-over';
    g.save();
    poly(g, top); g.clip();
    g.globalAlpha = 0.34 * day + 0.1;
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.drawImage(shadowCv, 0, 0);
    g.restore();
    g.setTransform(DPR, 0, 0, DPR, 0, 0);
  }

  /* blocks, back to front */
  const order = BLOCKS.map((b, i) => i).sort((a, b) => {
    const A = BLOCKS[a], B = BLOCKS[b];
    return ((A.x0 + A.x1) * syaw + (A.y0 + A.y1) * cyaw) - ((B.x0 + B.x1) * syaw + (B.y0 + B.y1) * cyaw);
  });
  hulls = [];
  /* Lambert on the walls, darkened by the share of the face in another block's shadow */
  const toneLo = mix(pal.white, pal.shade, 0.55);
  const lit = (n, frac) => {
    const lam = s.alt > 0 ? Math.max(0, n[0] * v[0] + n[1] * v[1] + n[2] * v[2]) : 0;
    const b = 0.42 + 0.58 * lam * day * (1 - 0.75 * frac);
    return css(mix(toneLo, pal.white, Math.max(0, Math.min(1, b))));
  };
  for (const i of order) {
    const b = BLOCKS[i];
    const c = [[b.x0, b.y0], [b.x1, b.y0], [b.x1, b.y1], [b.x0, b.y1]];
    const faces = [];
    for (let e = 0; e < 4; e++) {
      const f = (e + 1) % 4;
      const nx = Math.sign(c[f][1] - c[e][1]), ny = Math.sign(c[e][0] - c[f][0]);
      if (nx * syaw + ny * cyaw <= 0) continue;
      const corners = [[c[e][0], c[e][1], 0], [c[f][0], c[f][1], 0], [c[f][0], c[f][1], b.h], [c[e][0], c[e][1], b.h]];
      faces.push({ n: [nx, ny, 0], corners });
    }
    faces.push({ n: [0, 0, 1], corners: c.map(([x, y]) => [x, y, b.h]), roof: true });
    for (const f of faces) {
      const frac = s.alt > 0.002 ? faceShade(f.corners, v, i) : 0;
      poly(g, f.corners.map((p) => proj(p[0], p[1], p[2])));
      g.fillStyle = f.roof ? css(mix(toneLo, pal.white, 0.55 + 0.45 * day * (1 - 0.7 * frac))) : lit(f.n, frac);
      g.fill();
      g.strokeStyle = css(pal.ink, i === hoverB ? 0.7 : 0.22);
      g.lineWidth = i === hoverB ? 1.4 : 0.8;
      g.stroke();
    }
    /* storey lines on the visible walls */
    g.beginPath();
    for (const f of faces) {
      if (f.roof) continue;
      for (let z = STOREY; z < b.h - 0.1; z += STOREY) {
        const a = proj(f.corners[0][0], f.corners[0][1], z), q = proj(f.corners[1][0], f.corners[1][1], z);
        g.moveTo(a[0], a[1]); g.lineTo(q[0], q[1]);
      }
    }
    g.strokeStyle = css(pal.ink, 0.08); g.lineWidth = 0.7; g.stroke();
    const pts = [];
    for (const [x, y] of c) { pts.push(proj(x, y, 0)); pts.push(proj(x, y, b.h)); }
    hulls[i] = hull(pts.map((p) => [p[0], p[1]]));
  }

  sunPath(g, s, v, true);

}

/* A ground ring around the model: compass ticks, the day's arc of sun
   azimuths from sunrise to sunset, and the sun itself standing over its
   azimuth at its true altitude. Far parts draw before the blocks, near after. */
const RING = 76;
function sunPath(g, s, v, near) {
  if (!near) {
    g.beginPath();
    for (let a = 0; a <= 360; a += 4) {
      const p = proj(Math.sin(a * D) * RING, -Math.cos(a * D) * RING, 0);
      a ? g.lineTo(p[0], p[1]) : g.moveTo(p[0], p[1]);
    }
    g.strokeStyle = css(pal.ink, 0.13); g.lineWidth = 1; g.stroke();
    g.beginPath();
    for (let a = 0; a < 360; a += 30) {
      const p = proj(Math.sin(a * D) * RING, -Math.cos(a * D) * RING, 0);
      const q = proj(Math.sin(a * D) * (RING + (a % 90 ? 3 : 6)), -Math.cos(a * D) * (RING + (a % 90 ? 3 : 6)), 0);
      g.moveTo(p[0], p[1]); g.lineTo(q[0], q[1]);
    }
    g.strokeStyle = css(pal.ink, 0.35); g.stroke();
    /* azimuths swept by the sun today */
    g.beginPath();
    let on = false;
    for (let m = T0; m <= T1; m += 5) {
      const q = solar(m, decl);
      if (q.alt <= 0) { on = false; continue; }
      const p = proj(Math.sin(q.az) * RING, -Math.cos(q.az) * RING, 0);
      on ? g.lineTo(p[0], p[1]) : g.moveTo(p[0], p[1]);
      on = true;
    }
    g.strokeStyle = css(pal.sun, 0.7); g.lineWidth = 2.5; g.lineCap = 'round'; g.stroke();
    g.lineCap = 'butt';
    const n = proj(0, -(RING + 13), 0);
    g.font = '700 9px system-ui, sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillStyle = css(pal.ink, 0.7); g.fillText('N', n[0], n[1]);
  }
  if (s.alt <= 0) return;
  const foot = proj(Math.sin(s.az) * RING, -Math.cos(s.az) * RING, 0);
  if ((foot[2] > 0) !== near) return;
  const R = RING, p = proj(v[0] * R, v[1] * R, v[2] * R);
  g.beginPath(); g.moveTo(foot[0], foot[1]); g.lineTo(p[0], p[1]);
  g.setLineDash([2, 3]); g.strokeStyle = css(pal.sun, 0.9); g.lineWidth = 1; g.stroke(); g.setLineDash([]);
  g.beginPath(); g.arc(foot[0], foot[1], 2.5, 0, Math.PI * 2); g.fillStyle = css(pal.sun); g.fill();
  const glow = g.createRadialGradient(p[0], p[1], 0, p[0], p[1], 20);
  glow.addColorStop(0, css(pal.sun, 0.55)); glow.addColorStop(1, css(pal.sun, 0));
  g.fillStyle = glow; g.fillRect(p[0] - 20, p[1] - 20, 40, 40);
  g.beginPath(); g.arc(p[0], p[1], 5.5, 0, Math.PI * 2);
  g.fillStyle = css(pal.sun); g.fill();
  g.lineWidth = 1.5; g.strokeStyle = css(pal.white); g.stroke();
}

/* ── readouts ── */
const hhmm = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(Math.round(m % 60)).padStart(2, '0');
let lastRead = -1;
function readout(force) {
  const m = Math.round(minutes);
  if (!force && m === lastRead) return;
  lastRead = m;
  const s = solar(minutes, decl);
  const sh = plazaShade(s);
  clock.textContent = hhmm(Math.round(minutes / 5) * 5);
  if (s.alt > 0) {
    out.alt.textContent = Math.round(s.alt / D) + '°';
    out.az.textContent = 'az ' + Math.round(s.az / D) + '°';
    out.shade.textContent = Math.round(sh * 100) + '%';
  } else {
    out.alt.textContent = 'Below';
    out.az.textContent = 'horizon';
    out.shade.textContent = '—';
  }
  const date = radios.find((r) => r.checked).nextElementSibling.textContent;
  model.setAttribute('aria-label', 'Massing model, ' + date + ' at ' + clock.textContent + (s.alt > 0 ? ', sun ' + Math.round(s.alt / D) + ' degrees high, plaza ' + Math.round(sh * 100) + ' percent in shade' : ', sun below the horizon'));
  range.setAttribute('aria-valuetext', clock.textContent + (s.alt > 0 ? ', plaza ' + Math.round(sh * 100) + '% in shade' : ', night'));
}

/* ── loop: the day plays at 40 minutes a second ── */
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = Math.min(0.05, (now - (last || now)) / 1000);
  last = now;
  if (playing) {
    minutes += dt * 40;
    if (minutes > set) minutes = rise;
    if (minutes < rise) minutes = rise;
    range.value = Math.round(minutes / 5) * 5;
  }
  draw();
  readout();
  if (seen && playing) raf = requestAnimationFrame(frame);
}
function kick() { if (!raf && seen) { last = 0; raf = requestAnimationFrame(frame); } }
function setPlaying(p) {
  playing = p;
  playBtn.setAttribute('aria-pressed', p ? 'true' : 'false');
  playBtn.setAttribute('aria-label', p ? 'Pause the day' : 'Play the day');
  if (p) kick();
}

playBtn.addEventListener('click', () => setPlaying(!playing));
range.addEventListener('input', () => {
  setPlaying(false);
  minutes = Number(range.value);
  draw(); readout(true);
});
radios.forEach((r) => r.addEventListener('change', () => {
  decl = Number(r.value);
  buildCurve();
  if (playing && (minutes < rise || minutes > set)) minutes = rise;
  draw(); readout(true);
}));

/* ── rotate the model, hover the blocks ── */
let drag = null;
function local(e) { const r = model.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; }
function inside(p, h) {
  let c = false;
  for (let i = 0, j = h.length - 1; i < h.length; j = i++) {
    if ((h[i][1] > p[1]) !== (h[j][1] > p[1]) && p[0] < ((h[j][0] - h[i][0]) * (p[1] - h[i][1])) / (h[j][1] - h[i][1]) + h[i][0]) c = !c;
  }
  return c;
}
function pickBlock(p) {
  const order = BLOCKS.map((b, i) => i).sort((a, b) => {
    const A = BLOCKS[a], B = BLOCKS[b];
    return ((B.x0 + B.x1) * syaw + (B.y0 + B.y1) * cyaw) - ((A.x0 + A.x1) * syaw + (A.y0 + A.y1) * cyaw);
  });
  for (const i of order) if (hulls[i] && inside(p, hulls[i])) return i;
  return -1;
}
model.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  drag = { id: e.pointerId, x: e.clientX, moved: false };
});
model.addEventListener('pointermove', (e) => {
  if (drag && e.pointerId === drag.id) {
    const dx = e.clientX - drag.x;
    if (!drag.moved && Math.abs(dx) > 3) { drag.moved = true; model.setPointerCapture(e.pointerId); root.setAttribute('data-drag', ''); }
    if (drag.moved) { yaw += dx * 0.012; drag.x = e.clientX; draw(); }
    return;
  }
  const p = local(e);
  const b = pickBlock(p);
  if (b !== hoverB) { hoverB = b; draw(); }
  if (b >= 0) {
    const B = BLOCKS[b];
    out.bname.textContent = B.name;
    out.bmeta.textContent = B.fl + ' storeys · ' + B.h.toFixed(1) + ' m';
    const tw = tipEl.offsetWidth, th = tipEl.offsetHeight;
    tipEl.style.setProperty('--tx', Math.max(6, Math.min(W - tw - 6, p[0] + 12)) + 'px');
    tipEl.style.setProperty('--ty', Math.max(6, p[1] - th - 10) + 'px');
    root.setAttribute('data-tip', '');
  } else root.removeAttribute('data-tip');
});
function endDrag(e) {
  if (!drag || e.pointerId !== drag.id) return;
  drag = null;
  root.removeAttribute('data-drag');
}
model.addEventListener('pointerup', endDrag);
model.addEventListener('pointercancel', endDrag);
model.addEventListener('pointerleave', () => { if (hoverB >= 0) { hoverB = -1; draw(); } root.removeAttribute('data-tip'); });
model.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft') yaw -= 15 * D;
  else if (e.key === 'ArrowRight') yaw += 15 * D;
  else if (e.key === 'ArrowUp') elev = Math.min(80 * D, elev + 6 * D);
  else if (e.key === 'ArrowDown') elev = Math.max(20 * D, elev - 6 * D);
  else return;
  e.preventDefault();
  draw();
});

theme();
decl = Number(radios.find((r) => r.checked).value);
buildCurve();
if (calm.matches) minutes = 900;
range.value = Math.round(minutes / 5) * 5;
setPlaying(playing);
readout(true);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  resize();
});
ro.observe(cv);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  seen = entries[0].isIntersecting;
  if (seen) { draw(); kick(); }
});
io.observe(root);

css:
.fxd-moon {
  /* Re-theme with these three; the canvas reads them. */
  --fxd-moon-night: oklch(0.195 0.008 262);
  --fxd-moon-bone: oklch(0.94 0.022 86);
  --fxd-moon-accent: oklch(0.69 0.16 30);

  --fxd-moon-muted: color-mix(in oklch, var(--fxd-moon-bone) 55%, var(--fxd-moon-night));
  --fxd-moon-line: color-mix(in oklch, var(--fxd-moon-bone) 12%, transparent);

  container-type: inline-size;
  position: relative;
  isolation: isolate;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1;
  min-block-size: 300px;
  max-block-size: 390px;
  border-radius: 18px;
  overflow: hidden;
  background:
    radial-gradient(70% 60% at 50% 50%, color-mix(in oklch, var(--fxd-moon-night) 88%, var(--fxd-moon-bone)), transparent 70%),
    var(--fxd-moon-night);
  color: var(--fxd-moon-bone);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxd-moon-line);

  & .fxd-moon__dial {
    position: absolute;
    inset: 0;
    cursor: grab;
    touch-action: none;
    outline: none;
  }
  &[data-drag] .fxd-moon__dial { cursor: grabbing; }
  & .fxd-moon__dial:focus-visible { box-shadow: inset 0 0 0 2px var(--fxd-moon-accent); border-radius: inherit; }
  & .fxd-moon__cv {
    position: absolute;
    inset: 0;
    display: block;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxd-moon__probe { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }

  & .fxd-moon__head {
    position: absolute;
    inset: 0 auto auto 0;
    padding: clamp(12px, 4.4cqi, 18px);
    pointer-events: none;
  }
  & .fxd-moon__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxd-moon-muted);
  }
  & .fxd-moon__phase {
    margin: 4px 0 0;
    font-size: clamp(18px, 6.6cqi, 27px);
    font-weight: 260;
    letter-spacing: -.015em;
    line-height: 1.05;
    text-wrap: balance;
  }

  & .fxd-moon__read {
    position: absolute;
    left: clamp(12px, 4.4cqi, 18px);
    bottom: clamp(12px, 4.4cqi, 18px);
    display: flex;
    gap: clamp(12px, 5cqi, 22px);
    margin: 0;
