/* Halftone moon. A 45° dot lattice is laid over the disc once per resize;
   every dot is a point on an orthographic sphere with view normal n. Each
   frame n is turned by the libration (and any drag) into moon-fixed
   coordinates to look up albedo — maria, craters, fine noise — and lit in
   view space by a sun whose direction is set by the phase angle. The dot's
   radius is √(albedo × Lambert), so the terminator, the maria and the faint
   earthshine all fall out of one pass. */
const dial = root.querySelector('.fxd-moon__dial');
const cv = root.querySelector('.fxd-moon__cv');
const ctx = cv.getContext('2d');
const probe = root.querySelector('.fxd-moon__probe');
const playBtn = root.querySelector('.fxd-moon__play');
const k = (n) => root.querySelector('[data-k="' + n + '"]');
const out = { phase: k('phase'), age: k('age'), lit: k('lit'), rise: k('rise') };
const calm = matchMedia('(prefers-reduced-motion: reduce)');
if (!ctx) return;

const D = Math.PI / 180, MONTH = 29.53;
const vec = (lat, lon) => [Math.cos(lat * D) * Math.sin(lon * D), Math.sin(lat * D), Math.cos(lat * D) * Math.cos(lon * D)];
/* maria: centre lat, lon, angular radius, darkening */
const MARIA = [
  [18, -57, 25, 0.34], [33, -16, 15.5, 0.4], [28, 17, 9.5, 0.4], [8.5, 31, 11, 0.4], [17, 59, 7, 0.44],
  [-7.8, 51, 8.5, 0.34], [-15, 35, 5.5, 0.3], [-21, -17, 10, 0.3], [-24, -39, 6, 0.32], [13, 4, 5, 0.24],
  [7, -31, 7, 0.24], [56, -20, 6, 0.26], [57, 5, 6.5, 0.26], [55, 30, 5, 0.24], [-2, -14, 5, 0.18],
].map(([la, lo, r, d]) => ({ v: vec(la, lo), c: Math.cos(r * D), c2: Math.cos(r * 0.6 * D), d }));
/* named bright craters, then a seeded scatter of small ones */
const CRATERS = [[-43.3, -11.4, 3.2, 0.3], [9.6, -20.1, 3, 0.22], [8.1, -38, 2, 0.18], [23.7, -47.4, 1.8, 0.32], [51.6, -9.4, 3, -0.18]]
  .map(([la, lo, r, b]) => ({ v: vec(la, lo), r: r * D, b }));
{
  let s = 1969;
  const rnd = () => ((s = (s * 16807) % 2147483647) / 2147483647);
  for (let i = 0; i < 90; i++) {
    const z = rnd() * 2 - 1, a = rnd() * Math.PI * 2, q = Math.sqrt(1 - z * z);
    CRATERS.push({ v: [q * Math.cos(a), z, q * Math.sin(a)], r: (0.8 + rnd() * rnd() * 3.6) * D, b: 0 });
  }
}
/* Tycho's halo of rays, as a soft bright cap */
const TYCHO = vec(-43.3, -11.4), TYCHO_C = Math.cos(14 * D);

function hash(x, y, z) {
  let h = (x * 374761393 + y * 668265263 + z * 1274126177) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
function vnoise(x, y, z) {
  const xi = Math.floor(x), yi = Math.floor(y), zi = Math.floor(z);
  const xf = x - xi, yf = y - yi, zf = z - zi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf), w = zf * zf * (3 - 2 * zf);
  let r = 0;
  for (let c = 0; c < 8; c++) {
    const dx = c & 1, dy = (c >> 1) & 1, dz = c >> 2;
    r += hash(xi + dx, yi + dy, zi + dz) * (dx ? u : 1 - u) * (dy ? v : 1 - v) * (dz ? w : 1 - w);
  }
