}
function albedo(p) {
  let a = 0.86 + (vnoise(p[0] * 9 + 7, p[1] * 9, p[2] * 9) - 0.5) * 0.14;
  for (const m of MARIA) {
    const c = p[0] * m.v[0] + p[1] * m.v[1] + p[2] * m.v[2];
    if (c <= m.c) continue;
    /* ragged shoreline: wobble the edge with noise */
    const t = (c - m.c) / (m.c2 - m.c) + (vnoise(p[0] * 14, p[1] * 14 + 3, p[2] * 14) - 0.5) * 0.9;
    a -= m.d * Math.max(0, Math.min(1, t));
  }
  const ty = p[0] * TYCHO[0] + p[1] * TYCHO[1] + p[2] * TYCHO[2];
  if (ty > TYCHO_C) a += 0.12 * (ty - TYCHO_C) / (1 - TYCHO_C);
  for (const c of CRATERS) {
    const dot = p[0] * c.v[0] + p[1] * c.v[1] + p[2] * c.v[2];
    if (dot < 0.995 && c.r < 0.1) continue;
    const ang = Math.acos(Math.min(1, dot));
    if (ang > c.r * 1.25) continue;
    const x = ang / c.r;
    a += c.b * Math.max(0, 1 - x) + (x > 0.75 ? 0.07 * (1 - Math.abs(x - 0.95) * 5) : -0.05);
