/* ── palette ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const pal = {};
const css = (c, a = 1) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
function theme() { pal.bone = rgb('--fxd-moon-bone'); pal.accent = rgb('--fxd-moon-accent'); pal.night = rgb('--fxd-moon-night'); }

/* ── geometry ── */
let W = 0, H = 0, DPR = 1, R = 100, CX = 0, CY = 0, cell = 5;
let dots = null;                                   /* [sx, sy, nx, ny, nz] per dot */
function resize() {
  const r = cv.getBoundingClientRect();
  if (!r.width || !r.height) return;
  W = r.width; H = r.height;
  DPR = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  R = Math.min(W * 0.3, (H - 132) * 0.42);
  CX = W / 2; CY = H * 0.53;
  cell = Math.max(3.4, R / 25);
  const list = [], s = cell * Math.SQRT1_2, n = Math.ceil(R / s) + 2;
  for (let i = -n; i <= n; i++) for (let j = -n; j <= n; j++) {
    const x = (i - j) * s, y = (i + j) * s;
    const nx = x / R, ny = -y / R, q = nx * nx + ny * ny;
    if (q >= 1) continue;
    list.push(CX + x, CY + y, nx, ny, Math.sqrt(1 - q));
  }
  dots = new Float32Array(list);
  draw();
}

/* ── state ── */
let age = 10.9, playing = !calm.matches, seen = false, raf = 0, last = 0;
let lonU = 0, latU = 0, lonL = 0, latL = 0, idleAt = -1e9, drag = null;

function phaseName(a) {
  if (a < 1 || a >= 28.53) return 'New moon';
  if (a < 6.38) return 'Waxing crescent';
  if (a < 8.38) return 'First quarter';
  if (a < 13.77) return 'Waxing gibbous';
  if (a < 15.77) return 'Full moon';
  if (a < 21.15) return 'Waning gibbous';
  if (a < 23.15) return 'Last quarter';
  return 'Waning crescent';
}

function draw() {
  if (!dots || !pal.bone) return;
  const g = ctx;
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  g.clearRect(0, 0, W, H);
  const ph = (age / MONTH) * Math.PI * 2;
  const L = [Math.sin(ph), 0, -Math.cos(ph)];
  const lit = (1 - Math.cos(ph)) / 2;
  const earth = 0.05 * (1 - lit);
  /* view → moon-fixed: undo the pitch, then the yaw */
  const lon = (lonU + lonL) * D, lat = (latU + latL) * D;
  const cy = Math.cos(lon), sy = Math.sin(lon), cp = Math.cos(lat), sp = Math.sin(lat);

  /* the limb, faint, so the unlit disc still reads */
  g.beginPath(); g.arc(CX, CY, R + 0.5, 0, Math.PI * 2);
  g.strokeStyle = css(pal.bone, 0.1); g.lineWidth = 1; g.stroke();

  const path = new Path2D();
  const p = [0, 0, 0];
  for (let i = 0; i < dots.length; i += 5) {
    const nx = dots[i + 2], ny = dots[i + 3], nz = dots[i + 4];
    let lam = nx * L[0] + nz * L[2];
    const b0 = lam > 0 ? Math.pow(lam, 0.8) : 0;
    if (b0 <= 0 && earth < 0.012) continue;
    const y1 = ny * cp + nz * sp, z1 = -ny * sp + nz * cp;
    p[0] = nx * cy - z1 * sy; p[1] = y1; p[2] = nx * sy + z1 * cy;
    const b = albedo(p) * (b0 * (0.86 + 0.14 * nz) + earth);
    const r = cell * 0.57 * Math.sqrt(Math.max(0, b));
    if (r < 0.3) continue;
    path.moveTo(dots[i] + r, dots[i + 1]);
    path.arc(dots[i], dots[i + 1], r, 0, Math.PI * 2);
  }
  g.fillStyle = css(pal.bone);
  g.fill(path);

  /* the dial: a tick per day, quarters marked, today in the accent */
  const Rd = R + Math.max(14, R * 0.15);
  g.lineCap = 'round';
  for (let d = 0; d < 30; d++) {
    const a = -Math.PI / 2 + (d / MONTH) * Math.PI * 2;
    const major = d % 7 === 0 && d < 29;
    const r0 = Rd, r1 = Rd + (major ? 7 : 4);
    g.beginPath();
    g.moveTo(CX + Math.cos(a) * r0, CY + Math.sin(a) * r0);
    g.lineTo(CX + Math.cos(a) * r1, CY + Math.sin(a) * r1);
