  [[0, 0], [7.38, 0.5], [14.77, 1], [22.15, 0.5]].forEach(([d, f], i) => {
    const a = -Math.PI / 2 + (d / MONTH) * Math.PI * 2, rr = Rd + 16;
    const x = CX + Math.cos(a) * rr, y = CY + Math.sin(a) * rr;
    g.beginPath(); g.arc(x, y, 3.6, 0, Math.PI * 2);
    g.strokeStyle = css(pal.bone, 0.55); g.lineWidth = 1; g.stroke();
    if (f === 1) { g.fillStyle = css(pal.bone, 0.8); g.fill(); }
    if (f === 0.5) { g.beginPath(); g.arc(x, y, 3.6, -Math.PI / 2, Math.PI / 2, i === 3); g.closePath(); g.fillStyle = css(pal.bone, 0.8); g.fill(); }
