  const rise = Math.round(((6 * 60 + (age / MONTH) * 1440) % 1440) / 5) * 5;
  const hh = String(Math.floor(rise / 60) % 24).padStart(2, '0') + ':' + String(rise % 60).padStart(2, '0');
  const t = age.toFixed(1) + name + lit + hh;
  if (t === lastText) return;
  lastText = t;
  out.age.textContent = age.toFixed(1);
  out.lit.textContent = lit;
  out.rise.textContent = hh;
  if (out.phase.textContent !== name) out.phase.textContent = name;
